let state={access:null,patients:[],appointments:[],consultations:[],prescriptions:[],medicines:[],batches:[],sales:[],adjustments:[],suppliers:[],purchaseOrders:[],editHistory:[],employees:[],settings:{pharmacyName:''},blockHistory:[],invoices:[],cashMovements:[],closings:[],stocktakes:[],events:[],revision:0},tab='catalogue',mode='medicine',cart=[],saleToken=uuid(),busy=false,storageOK=true,formRevision=0;
try{const raw=localStorage.getItem(key);if(raw){const loaded=JSON.parse(raw);state={...P.validateBackup({app:'retail-pharmacy-offline',version:13,data:loaded}),revision:loaded.revision||0};}localStorage.setItem(key,JSON.stringify(state));}catch(e){storageOK=false;$('#notice').classList.add('error');$('#notice').textContent='Browser storage is blocked or contains invalid data. Saving is disabled. Keep this file in Chrome or Edge with normal browsing enabled. Existing saved data has not been overwritten.';}
function persist(next,expected=state.revision){if(!storageOK)throw Error('Saving is unavailable. Check browser storage.');const latest=JSON.parse(localStorage.getItem(key)||'{}');if((latest.revision||0)!==expected){throw Error('Records changed in another tab. Reload before saving; your current changes have not been saved.');}next.revision=expected+1;localStorage.setItem(key,JSON.stringify(next));state=next;}
