function go(next){tab=next;const labels={accounts:['Accounts & access','Accounts, permissions and reports','Approved accounts, pharmacy roles, action history and email previews.'],patients:['Patients','Patient health records','Patient details, history, consultations and dated amendments.'],appointments:['Appointments','Appointments','Book visits and track appointment outcomes.'],prescriptions:['Prescriptions','Prescription records','Record clinician prescriptions with multiple medicines and full directions.'],stocktake:['Stocktake','Count stock by shelf','Save physical counts, explain differences and post batch adjustments.'],closing:['Daily closing','Close the day’s cash drawer','Review sales by payment method and reconcile counted cash.'],invoices:['Invoicing','Customer invoices','Prepare invoices, track unpaid amounts and record full payment.'],losses:['Stock loss','Stock losses by medicine','Quantities and purchase costs lost, with reasons and traceable records.'],movements:['Stock movements','Follow every stock movement','Deliveries, sales and adjustments by receipt batch.'],catalogue:['Medicines','Medicine catalogue','Manage medicines, pack sizes and stock.'],batches:['Batch inventory','Know every batch','Received quantities, remaining stock, expiry dates and purchase costs.'],checkout:['Checkout','Make a sale','Choose the brand, check the batch and record payment.'],sales:['Sales & receipts','Every sale, recorded','Review completed transactions and print a receipt again.'],employees:['Employees','Employee directory','Staff details and employment status. These records do not create login accounts.'],shelves:['Shelf locations','Find stock by shelf','Batch locations, receipt order and expiry dates.'],alerts:['Stock alerts','Know what needs attention','Low stock, open orders and expiry checks in one place.'],history:['Edit history','Review record corrections','Who changed a record, when and why, with previous and revised values.'],procurement:['Suppliers & orders','Plan purchases and track deliveries','Prepare orders, record partial deliveries and see what is still outstanding.'],profit:['Drug profit & loss','Profit and loss on medicines sold','Compare sales income against the purchase cost of the units sold.'],brands:['Brand comparison','Compare the full stock picture','Receipts, stock on hand, expiry exposure and sales by brand.'],adjustments:['Stock adjustments','Keep stock counts accurate','Record count differences and stock removals with a reason and history.'],blocks:['Blocked list','Stock holds and supplier suspensions','Record holds, releases and permanent stock write-offs independently.'],backup:['Settings','Pharmacy settings and backups','Save a copy before updating, moving the file or changing browsers.']};$('#breadcrumb').textContent=labels[tab][0];$('#heading').textContent=labels[tab][1];$('#subtitle').textContent=labels[tab][2];$('#search').value='';$('#status').value='all';document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));render();}
const field=(label,name,type='text',value='',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
function openForm(kind,id){receivingOrder=null;mode=kind;formRevision=state.revision;$('#form').reset();$('#error').textContent='';$('#form-kicker').textContent=kind==='medicine'?'BUILD YOUR CATALOGUE':'RECORD A DELIVERY';$('#form-title').textContent=kind==='medicine'?'Add medicine':'Receive stock';$('#calculation').hidden=kind==='medicine';$('#fields').innerHTML=kind==='medicine'?field('Generic name *','generic','text','','required maxlength="100"')+field('Brand name *','brand','text','','required maxlength="100"')+field('Strength *','strength','text','','required maxlength="60"')+`<label>Dosage form *<select name="form" required><option value="">Select form</option>${['Tablet','Capsule','Oral solution','Oral suspension','Cream','Ointment','Gel','Injection','Prefilled injection','Infusion','Drops','Spray','Inhaler','Powder','Granules','Suppository','Pessary','Transdermal patch','Other'].map(s=>`<option>${s}</option>`).join('')}</select></label>`+field('Smallest counting unit *','unit','text','','required placeholder="Tablet, bottle, tube…" maxlength="30"')+field('Units per purchase pack *','packSize','number','100','required min="1" step="1"')+field('Selling price / unit (UGX) *','price','number','','required min="0" max="1000000000000" step="0.01"')+field('Low-stock level (units) *','low','number','100','required min="0" step="1"')+field('Shelf location','shelf','text','','maxlength="40"')+`<p class="note">For unbranded stock, enter the labelled product name and manufacturer. Brand is required. Use the same generic, strength and form wording for brand comparisons.</p>`:`<label class="full">Medicine & brand *<select name="medicineId" required><option value="">Select medicine</option>${state.medicines.map(m=>`<option value="${esc(m.id)}" ${m.id===id?'selected':''}>${esc(m.generic)} ${esc(m.strength)} · ${esc(m.brand)} (${esc(m.form)})</option>`).join('')}</select></label>`+`<label>Supplier *<select name="supplierId" required><option value="">Select saved supplier</option>${state.suppliers.map(s=>`<option value="${esc(s.id)}" ${s.status==='suspended'?'disabled':''}>${esc(s.name)}${s.status==='suspended'?' (on hold)':''}</option>`).join('')}</select><small class="note">Add new suppliers in Suppliers &amp; orders first.</small></label>`+field('Supplier invoice *','invoice','text','','required maxlength="80"')+field('Received date *','date','date',today(),'required max="'+today()+'"')+field('Batch number *','batch','text','','required maxlength="80"')+field('Expiry month *','expiry','month','','required min="'+today().slice(0,7)+'"')+field('Packs received *','packs','number','','required min="1" step="1"')+field('Purchase cost (UGX) *','cost','number','','required min="0.01" max="1000000000000" step="0.01"');if(kind==='medicine')mountPackEditor($('#fields'));else mountReceiveUnits();$('#dialog').showModal();calculate();}
function calculate(){if(mode!=='receive')return;syncReceiveUnits();const d=Object.fromEntries(new FormData($('#form'))),m=state.medicines.find(m=>m.id===(receivingOrder?.medicineId||d.medicineId));if(!m){$('#calculation').textContent='Select a medicine.';return;}const c=receiptPackConfig(m),unit=receivingOrder?c.purchaseUnit:d.purchaseUnit||c.purchaseUnit,factor=Packs.factor(c,unit),qty=Number(d.packs)*factor,cost=Number(d.cost);$('#fields [name="packs"]').closest('label').firstChild.textContent='Number of '+unit+' received *';$('#calculation').textContent=qty>0?`${d.packs} ${unit} × ${factor} ${m.unit} = ${qty.toLocaleString()} ${m.unit} to add · Total cost: ${money(cost)} · Cost per ${unit}: ${money(cost/Number(d.packs))}`:`1 ${unit} contains ${factor} ${m.unit}. Enter the quantity received.`;}

$('#form').addEventListener('input',calculate);$('#form').onsubmit=e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));for(const k in d)d[k]=d[k].trim();if(receivingOrder)d.medicineId=receivingOrder.medicineId;const next=structuredClone(state);if(mode==='medicine'){const packConfig=readPackEditor($('#fields'),d);d.unit=packConfig.baseUnit;d.packSize=Packs.factor(packConfig);const m=P.validateMedicine({...d,packConfig,id:uuid(),packSize:Number(d.packSize),price:Number(d.price),low:Number(d.low)},state.medicines);next.medicines.push(m);next.events.push({at:new Date().toISOString(),action:'Medicine added',id:m.id});}else{const m=state.medicines.find(m=>m.id===d.medicineId),b=receivingOrder?P.receiveOrder(state,receivingOrder.orderId,receivingOrder.medicineId,{...d,packs:Number(d.packs),cost:Number(d.cost)},today()):P.receiveFromSupplier(state,d.medicineId,{...d,packs:Number(d.packs),cost:Number(d.cost)},today());if(state.batches.some(x=>x.medicineId===b.medicineId&&P.norm(x.batch)===P.norm(b.batch)&&P.norm(x.invoice)===P.norm(b.invoice)&&P.norm(x.supplier)===P.norm(b.supplier)))throw Error('This batch is already recorded for this supplier invoice.');if(state.batches.some(x=>x.medicineId===b.medicineId&&P.norm(x.batch)===P.norm(b.batch)&&x.expiry!==b.expiry))throw Error('This batch already has a different expiry date.');b.id=uuid();next.batches.push(b);next.events.push({at:new Date().toISOString(),action:'Stock received',id:b.id});}persist(next,formRevision);$('#dialog').close();render();toast(mode==='medicine'?'Medicine added':'Stock received and saved');}catch(err){$('#error').textContent=err.message;focusPackError($('#fields'));}};
function renderCheckout(){const options=state.medicines.map(m=>`<option value="${esc(m.id)}">${esc(m.generic)} ${esc(m.strength)} · ${esc(m.brand)} (${available(m)} ${esc(m.unit)} available)</option>`).join('');$('#content').innerHTML=`<div class="section-body checkout-grid"><div><div class="checkout-box"><h3>Add to basket</h3><label>Medicine & brand<select id="sale-medicine"><option value="">Select medicine</option>${options}</select></label><label>Batch · earliest expiry suggested<select id="sale-batch"><option value="">Select medicine first</option></select></label><label>Quantity in stock units<input id="sale-qty" type="number" min="1" step="1" value="1"></label><p id="batch-hint" class="muted"></p><button id="cart-add" class="full-button">Add to basket</button></div><p class="note">Expired and quarantined batches are excluded. Payment confirmation is manual. A receipt records a sale; it is not a prescription or dosing instruction.</p></div><div class="checkout-box"><h3>Current basket</h3><div id="basket"></div><div class="total-line"><span>Total</span><span id="sale-total"></span></div><label>Payment method<select id="pay-method"><option>Cash</option><option>Mobile money</option><option>Bank / card</option></select></label><div id="pay-fields"></div><p id="checkout-error" role="alert" style="color:#a43c3c"></p><button id="complete-sale" class="full-button">Complete sale</button></div></div>`;$('#sale-medicine').onchange=refreshBatchChoices;$('#sale-batch').onchange=()=>{const b=state.batches.find(b=>b.id===$('#sale-batch').value);$('#sale-qty').max=b?P.basketRemaining(state,cart,b):0;};$('#cart-add').onclick=()=>{try{const batchId=$('#sale-batch').value,qty=Number($('#sale-qty').value),b=state.batches.find(b=>b.id===batchId);if(!b)throw Error('Select an available batch.');const already=cart.filter(l=>l.batchId===batchId).reduce((a,l)=>a+l.qty,0);if(!Number.isSafeInteger(qty)||qty<1||qty+already>left(b))throw Error('Only '+Math.max(0,left(b)-already)+' units remain to add from this batch.');const existing=cart.find(l=>l.batchId===batchId);if(existing)existing.qty+=qty;else cart.push({batchId,qty});$('#checkout-error').textContent='';renderBasket();}catch(e){$('#checkout-error').textContent=e.message;}};$('#pay-method').onchange=renderPayment;$('#complete-sale').onclick=completeSale;renderBasket();renderPayment();invoiceCheckoutControls();wirePackCheckout();}
function cartTotal(){return P.cash(cart.reduce((a,l)=>a+packCartQuote(l).total,0));}
function renderBasket(){$('#basket').innerHTML=cart.length?cart.map((l,i)=>{const b=state.batches.find(b=>b.id===l.batchId),m=state.medicines.find(m=>m.id===b.medicineId);return `<div class="cart-row"><div><strong>${esc(m.brand)} · ${esc(m.strength)}</strong><small>${esc(m.generic)} · ${esc(b.batch)}</small><small>${packCartLabel(l,m)}</small></div><div class="right"><strong>${money(packCartQuote(l).total)}</strong><br><button class="link" data-remove="${i}" aria-label="Remove ${esc(m.brand)} from basket">Remove</button></div></div>`}).join(''):'<p class="muted">Your basket is empty.</p>';$('#sale-total').textContent=money(cartTotal());$('#complete-sale').disabled=!cart.length||busy||!storageOK;document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{cart.splice(Number(b.dataset.remove),1);renderBasket();});updateChange();refreshStockChoices();}
function renderPayment(){const cash=$('#pay-method').value==='Cash';$('#pay-fields').innerHTML=cash?`<label>Cash received (UGX)<input id="cash-received" type="number" min="0" step="0.01" placeholder="Enter amount received"></label><p id="cash-change" class="muted">Enter cash received to calculate change.</p>`:`<label>Transaction reference<input id="payment-reference" maxlength="160" placeholder="Enter verified reference"></label><label class="checkbox-label"><input id="payment-confirmed" type="checkbox">I checked that this payment was received.</label>`;if(cash)$('#cash-received').oninput=updateChange;}
function updateChange(){if(!$('#cash-change'))return;const n=Number($('#cash-received').value),diff=P.cash(n-cartTotal());$('#cash-change').textContent=$('#cash-received').value===''?'Enter cash received to calculate change.':diff<0?'Amount still due: '+money(-diff):'Change: '+money(diff);}
function completeSale(){if(busy)return;busy=true;$('#complete-sale').disabled=true;try{const payment={method:$('#pay-method').value,tendered:$('#cash-received')?.value,reference:$('#payment-reference')?.value||'',confirmed:$('#payment-confirmed')?.checked||false},at=new Date().toISOString();let next,s;if(activeInvoice){next=P.settleInvoice(state,activeInvoice,payment,today(),saleToken,at);s=next.sales.at(-1);}else{s=P.sale(state,cart,payment,today(),saleToken,at);next=structuredClone(state);next.sales.push(s);}next.events.push({action:'Sale completed',id:s.id,at:s.at});persist(next);activeInvoice=null;cart=[];saleToken=uuid();render();showReceipt(s.id);toast('Sale saved. Batch stock updated.');}catch(e){$('#checkout-error').textContent=e.message;}finally{busy=false;if($('#complete-sale'))$('#complete-sale').disabled=!cart.length||!storageOK;}}
function saleCount(s){const summary=P.saleSummary(s.lines);return `<strong>${summary.items} ${summary.items===1?'item':'items'}</strong><small>${summary.units.map(u=>`${u.qty.toLocaleString()} ${esc(u.unit)}`).join(' · ')}</small>`;}
function saleNames(s){const line=l=>`<div class="sale-product"><small><b>${esc(l.brand)}</b> / ${esc(l.generic)} ${esc(l.strength)} · ${esc(l.form)}</small><small>${packLineLabel(l)} · Batch ${esc(l.batch)}</small></div>`;return s.lines.length>1?`<details><summary><span>${esc(s.lines[0].brand)} / ${esc(s.lines[0].generic)}</span><small>View all ${s.lines.length} medicine / batch lines</small></summary>${s.lines.map(line).join('')}</details>`:line(s.lines[0]);}
function showReceipt(id){$('#print-receipt').textContent='Print receipt';const s=state.sales.find(s=>s.id===id);$('#receipt-content').innerHTML=`<div class="receipt-head"><small>${esc(s.pharmacyName||'Legacy pharmacy receipt')}</small><h2>Sales receipt</h2><p>${esc(s.receiptNo||('Legacy reference: '+s.id.toUpperCase()))}</p><p>${esc(s.date)} · ${esc(new Date(s.at).toLocaleTimeString('en-GB',{timeZone:'Africa/Kampala'}))} EAT</p><p>Payment: ${esc(s.method)}${s.reference?' · '+esc(s.reference):''}</p><div class="receipt-items">${saleCount(s)}</div></div>`+table(['ITEM / BRAND & GENERIC','BATCH','QTY / SELLING UNIT','UNIT PRICE','TOTAL'],s.lines.map((l,i)=>`<tr><td><strong>Item ${[...new Set(s.lines.map(x=>x.medicineId))].indexOf(l.medicineId)+1}</strong><small><b>${esc(l.brand)}</b> / ${esc(l.generic)} ${esc(l.strength)} · ${esc(l.form)}</small></td><td>${esc(l.batch)}</td><td>${packLineLabel(l)}</td><td>${money(l.sellPrice??l.unitPrice)} / ${esc(l.sellUnit||l.unit)}</td><td>${money(l.total)}</td></tr>`))+`<div class="receipt-summary"><span>Total paid</span><b>${money(s.total)}</b><span>${s.method==='Cash'?'Cash received':'Payment recorded'}</span><b>${money(s.tendered)}</b><span>Change</span><b>${money(s.change)}</b></div><p class="note">Prototype receipt · No tax calculation or fiscal-invoice integration. ${s.method==='Cash'?'':'Payment checked manually.'}</p>`;$('#receipt').showModal();}
function renderProfit(){$('#content').innerHTML=`<div class="section-body"><div class="compare-controls"><label>From<input id="profit-from" type="date"></label><label>To<input id="profit-to" type="date"></label><label>Show<select id="profit-status"><option value="all">All sold medicines</option><option value="profit">Profitable medicines</option><option value="loss">Loss-making medicines</option><option value="even">Break-even medicines</option></select></label><button class="secondary" id="profit-export">Export profit & loss CSV</button></div><p id="profit-error" role="alert"></p><p class="note">Gross profit / loss = sales income − purchase cost of the actual batch units sold. Margin = gross profit ÷ sales income. Stock purchases still on the shelf, stock adjustments, refunds, taxes and operating expenses are excluded. This is not the pharmacy’s net profit.</p><div id="profit-totals" class="stats"></div></div><div id="profit-table"></div>`;for(const id of ['profit-from','profit-to','profit-status'])$('#'+id).onchange=updateProfit;$('#profit-export').onclick=()=>{const report=profitReport();if(!report)return;csvFile('drug-profit-loss-'+today()+'.csv',[['From', $('#profit-from').value||'All time','To',$('#profit-to').value||'All time','Filter',$('#profit-status').value],['Brand','Generic','Strength','Form','Stock unit','Units sold','Sales receipts','Sales income UGX','Cost of units sold UGX','Gross profit or loss UGX','Margin %'],...report.rows.map(r=>[r.brand,r.generic,r.strength,r.form,r.unit,r.qty,r.receipts,r.revenue,r.cost,r.profit,r.margin===null?'':Number(r.margin.toFixed(2))])]);};updateProfit();}
function profitReport(){try{const report=P.salesProfit(state.sales,$('#profit-from').value,$('#profit-to').value),filter=$('#profit-status').value;report.rows=report.rows.filter(r=>filter==='all'||(filter==='profit'&&r.profit>0)||(filter==='loss'&&r.profit<0)||(filter==='even'&&r.profit===0)).sort((a,b)=>a.profit-b.profit||a.brand.localeCompare(b.brand));$('#profit-error').textContent='';return report;}catch(e){$('#profit-error').textContent=e.message;return null;}}
function updateProfit(){const report=profitReport();if(!report){$('#profit-totals').innerHTML='';$('#profit-table').innerHTML='';$('#profit-export').disabled=true;return;}$('#profit-export').disabled=false;$('#profit-totals').innerHTML=[['Sales income',money(report.revenue)],['Cost of units sold',money(report.cost)],['Gross profit / loss',money(report.profit)],['Gross margin',report.margin===null?'—':report.margin.toFixed(1)+'%']].map(([label,value])=>`<div class="stat"><label>${label}</label><strong>${value}</strong><span>All sales in selected dates</span></div>`).join('');$('#profit-table').innerHTML=lossPanel()+table(['BRAND / GENERIC','UNITS SOLD','SALES RECEIPTS','SALES INCOME','COST OF UNITS SOLD','GROSS PROFIT / LOSS','MARGIN'],report.rows.map(r=>`<tr><td><strong>${esc(r.brand)}</strong><small>${esc(r.generic)} ${esc(r.strength)} · ${esc(r.form)}</small></td><td>${r.qty.toLocaleString()} ${esc(r.unit)}</td><td>${r.receipts}</td><td>${money(r.revenue)}</td><td>${money(r.cost)}</td><td><strong>${money(r.profit)}</strong><small class="${r.profit<0?'loss-text':''}">${r.profit<0?'Loss':r.profit>0?'Profit':'Break even'}</small></td><td>${r.margin===null?'—':r.margin.toFixed(1)+'%'}</td></tr>`),'No sold medicines match these dates and filters.');}
function renderBrands(){const groups=[...new Set(state.medicines.map(P.group))];$('#content').innerHTML=`<div class="section-body"><div class="compare-controls"><label>Medicine group<select id="group-filter"><option value="">All medicine groups</option>${groups.map(g=>{const m=state.medicines.find(m=>P.group(m)===g);return `<option value="${esc(g)}">${esc(m.generic)} ${esc(m.strength)} · ${esc(m.form)}</option>`}).join('')}</select></label><label>Rank by<select id="metric-filter"><option value="available">Available stock</option><option value="received">Stock received</option><option value="receipts">Receipt entries</option><option value="stockValue">Available stock value</option><option value="sold">Units sold</option><option value="revenue">Sales revenue</option><option value="profit">Gross profit on sales</option><option value="soon">Expiring within 90 days</option><option value="blocked">Expired / quarantined units</option></select></label><button class="secondary" id="brand-export">Export comparison CSV</button></div><p class="note">All-time receipts and sales; inventory is current. Compare the same generic, strength, form and stock unit. Received + net adjustments − sold = on hand. Available excludes expired and quarantined units. Sales alone do not establish patient preference.</p></div><div id="brand-results"></div>`;$('#group-filter').onchange=drawBrands;$('#metric-filter').onchange=drawBrands;$('#brand-export').onclick=exportBrands;drawBrands();}
function brandRows(){const selected=$('#group-filter').value;return state.medicines.filter(m=>!selected||P.group(m)===selected).map(m=>({m,...P.brandMetrics(state,m,today())}));}
function drawBrands(){const rows=brandRows(),metric=$('#metric-filter').value,groups=[...new Set(rows.map(r=>P.group(r.m)+'|'+P.norm(r.m.unit)))];$('#brand-results').innerHTML=groups.length?groups.map(g=>{const rs=rows.filter(r=>P.group(r.m)+'|'+P.norm(r.m.unit)===g).sort((a,b)=>b[metric]-a[metric]);const m=rs[0].m;return `<div class="brand-group"><h3>${esc(m.generic)} ${esc(m.strength)} · ${esc(m.form)} <span class="muted">/ ${esc(m.unit)}</span></h3>${table(['BRAND','RECEIVED','ADJUSTMENTS','ON HAND','AVAILABLE','RECEIPTS / SUPPLIERS','STOCK VALUE','EXPIRY / BLOCKED','SALES','GROSS PROFIT'],rs.map(r=>`<tr><td><strong>${esc(r.brand)}</strong><small>Last receipt: ${esc(r.lastReceipt||'None')}</small></td><td>${r.received.toLocaleString()}<small>Purchased: ${money(r.purchased)}</small></td><td>${r.adjusted>0?'+':''}${r.adjusted}<small>Value: ${money(r.adjustmentValue)}</small></td><td>${r.physical.toLocaleString()}</td><td><strong>${r.available.toLocaleString()}</strong><small>${r.available<=r.m.low?'Low / no stock':'Above alert level'}</small></td><td>${r.receipts} entries<small>${r.suppliers} suppliers</small></td><td>${money(r.stockValue)}</td><td>${r.soon} near expiry<small>${r.blocked} blocked</small></td><td>${r.sold} units<small>${money(r.revenue)}</small></td><td>${money(r.profit)}<small>Before expenses / stock losses</small></td></tr>`))}</div>`}).join(''):'<div class="empty">Add medicines to begin comparing brands.</div>';}
function csvFile(name,rows){const csv=rows.map(r=>r.map(v=>'"'+(typeof v==='string'?v.replace(/^[=+@-]/,"' $&"):String(v??'')).replace(/"/g,'""')+'"').join(',')).join('\r\n');download(name,'\ufeff'+csv,'text/csv;charset=utf-8');}
function exportBrands(){csvFile('brand-comparison-'+today()+'.csv',[['Generic','Strength','Form','Stock unit','Brand','Received units','Purchase cost UGX','Net adjustments','Adjustment value UGX','On hand','Available','Receipt entries','Suppliers','Last receipt','Available stock value UGX','Expiring in 90 days','Blocked units','Sold units','Revenue UGX','Gross profit on sales UGX'],...brandRows().map(r=>[r.m.generic,r.m.strength,r.m.form,r.m.unit,r.brand,r.received,r.purchased,r.adjusted,r.adjustmentValue,r.physical,r.available,r.receipts,r.suppliers,r.lastReceipt,r.stockValue,r.soon,r.blocked,r.sold,r.revenue,r.profit])]);}
function renderAdjustments(){const rows=[...state.adjustments].reverse();$('#content').innerHTML=`<div class="section-body"><div class="row-actions"><button id="adjust-open">＋ Record stock adjustment</button><button class="secondary" id="adjust-export">Export adjustment history</button></div><p class="note">A physical count correction sets the recorded quantity to the counted quantity. Other reasons remove units. Original receipts and sales remain unchanged. An incorrect adjustment can be corrected with another physical count entry and an explanatory note. Supplier returns here change stock only.</p></div>`+table(['DATE / RECORDED BY','BRAND / GENERIC','BATCH','REASON / NOTE','BEFORE','CHANGE','AFTER','VALUE CHANGE'],rows.map(a=>{const b=state.batches.find(b=>b.id===a.batchId),m=state.medicines.find(m=>m.id===a.medicineId);return `<tr><td>${esc(a.date)}<small>${esc(a.recordedBy)}</small></td><td><strong>${esc(m.brand)}</strong><small>${esc(m.generic)} ${esc(m.strength)} · ${esc(m.form)}</small></td><td>${esc(b.batch)}</td><td class="wrap-cell">${esc(a.reason)}<small>${esc(a.note)}</small></td><td>${a.before}</td><td>${a.delta>0?'+':''}${a.delta}</td><td>${a.after}</td><td>${money(a.value)}</td></tr>`}),'No stock adjustments recorded.');$('#adjust-open').onclick=openAdjustment;$('#adjust-export').onclick=()=>csvFile('stock-adjustments-'+today()+'.csv',[['Date','Recorded by','Brand','Generic','Strength','Form','Batch','Reason','Note','Before','Change','After','Value change UGX'],...rows.map(a=>{const b=state.batches.find(b=>b.id===a.batchId),m=state.medicines.find(m=>m.id===a.medicineId);return [a.date,a.recordedBy,m.brand,m.generic,m.strength,m.form,b.batch,a.reason,a.note,a.before,a.delta,a.after,a.value]})]);}
function openAdjustment(){formRevision=state.revision;$('#adjust-form').reset();$('#adjust-error').textContent='';$('#adjust-fields').innerHTML=`<label class="full">Medicine / brand / batch<select id="adjust-batch" required><option value="">Select batch</option>${state.batches.map(b=>{const m=state.medicines.find(m=>m.id===b.medicineId);return `<option value="${esc(b.id)}">${esc(m.brand)} · ${esc(m.generic)} ${esc(m.strength)} · ${esc(b.batch)} (${left(b)} on hand)</option>`}).join('')}</select></label><label>Reason<select id="adjust-reason"><option>Physical count correction</option><option>Damaged stock</option><option>Expired stock disposal</option><option>Supplier return</option><option>Other stock loss</option></select></label><label><span id="adjust-qty-label">Physical count (units)</span><input id="adjust-qty" type="number" min="0" step="1" required></label><label class="full">Explanation / reference *<textarea id="adjust-note" maxlength="500" required placeholder="Explain the difference or removal; include a reference if available."></textarea></label><label class="full">Recorded by *<input id="adjust-by" maxlength="100" required></label>`;$('#adjust-batch').onchange=adjustPreview;$('#adjust-reason').onchange=adjustPreview;$('#adjust-qty').oninput=adjustPreview;$('#adjust-dialog').showModal();adjustPreview();}
function adjustPreview(){const b=state.batches.find(b=>b.id===$('#adjust-batch').value),count=$('#adjust-reason').value==='Physical count correction';$('#adjust-qty-label').textContent=count?'Physical count (units)':'Quantity to remove (units)';$('#adjust-qty').min=count?'0':'1';if(!b){$('#adjust-preview').textContent='Select a batch to see its current stock.';return;}const before=left(b),qty=Number($('#adjust-qty').value),after=count?qty:before-qty;$('#adjust-preview').textContent=$('#adjust-qty').value===''?`Current on hand: ${before} units`:`Before: ${before} → After: ${after} units · Change: ${after-before} · Value change: ${money((after-before)*b.unitCost)}`;}
$('#adjust-form').onsubmit=e=>{e.preventDefault();try{const input={batchId:$('#adjust-batch').value,reason:$('#adjust-reason').value,count:Number($('#adjust-qty').value),quantity:Number($('#adjust-qty').value),note:$('#adjust-note').value,recordedBy:$('#adjust-by').value};const a=P.adjust(state,input,today(),uuid(),new Date().toISOString()),next=structuredClone(state);next.adjustments.push(a);next.events.push({action:'Stock adjusted',id:a.id,at:a.at});persist(next,formRevision);$('#adjust-dialog').close();render();toast('Stock adjustment recorded.');}catch(e){$('#adjust-error').textContent=e.message;}};
$('#adjust-close').onclick=()=>$('#adjust-dialog').close();$('#adjust-cancel').onclick=()=>$('#adjust-dialog').close();
function download(name,data,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const backupPayload=()=>({app:'retail-pharmacy-offline',version:13,exportedAt:new Date().toISOString(),data:state});
function backup(){download('pharmacy-backup-'+today()+'.json',JSON.stringify(backupPayload(),null,2),'application/json');toast('Backup download started. Keep the JSON file somewhere safe.');}
function renderBackup(){$('#content').innerHTML=pharmacySettingsHTML()+`<div class="section-body help-grid"><div><h2>Your portable records</h2><p id="backup-summary">${state.medicines.length} medicines · ${state.batches.length} batches · ${state.sales.length} sales · ${state.adjustments.length} adjustments · ${state.suppliers.length} suppliers · ${state.purchaseOrders.length} orders · ${state.employees.length} employees · ${state.patients.length} patients · ${state.appointments.length} appointments · ${state.consultations.length} consultations · ${state.prescriptions.length} prescriptions.</p><button id="download-backup">Download backup</button> <button id="restore-backup" class="secondary">Restore backup</button><p>A backup contains your catalogue, batches, sales, adjustments, suppliers, purchase orders, employees, invoices, daily closings, cash movements, stocktakes, patients, appointments, consultations, prescriptions, pharmacy settings, block history, edit history and local activity records. Clinical information is stored as readable text in these JSON backups; use fictional patient records only until secure access and storage are implemented. Restore replaces the records currently open in this browser, after confirmation. Back up first.</p><h3>When you update index.html</h3><ol><li>Download a JSON backup from the old version.</li><li>Keep the new index.html in your pharmacy folder.</li><li>Open it in the same browser. If records are missing, restore your JSON backup. Backups from version 0.2 are also supported.</li></ol><p>Changing file location, browser or clearing browsing data may make local records unavailable. The HTML file itself does not contain your entered records.</p></div><div><h2>Getting started</h2><p>Press <kbd>N</kbd> or use Quick checkout to open Checkout and focus the medicine search. The shortcut pauses while you type or have a dialog open. Your current basket is kept. Space Grotesk is embedded for offline use.</p><ol><li>Add a medicine with its generic and mandatory brand name. Configure its smallest unit, packaging levels and stock unit under Stock and selling units.</li><li>Receive stock with batch, expiry, packs and purchase cost.</li><li>In Checkout, select the brand and an available batch.</li><li>Choose a selling unit, enter the number of packs or individual units, add to basket and record payment.</li><li>Complete the sale, then print or save the receipt as PDF.</li></ol><h3>Try the workflow</h3><button id="load-demo" class="secondary" >${demoMode?'Explore demo medicines':'Open demo workspace'}</button><p>Try every workflow using separate, fictional records. Reset the demo whenever you want.</p><h3>Current scope</h3><p>Single-device prototype. Use one tab. No staff authentication, cloud backup, refunds, tax calculation or automated payment confirmation yet. Supplier stock returns do not record supplier credits or cash refunds. Local activity records are not a tamper-proof audit trail.</p><details><summary>Testing included with this version</summary><p>Version 0.20 adds responsive tables, more medicine pack layouts and one clear total-cost entry. Checks cover all 23 tabs, sample entry workflows, stock calculations, receipts and account permissions. Automated calculation and simulated form-workflow checks cover receiving, mixed-unit checkout, receipts, corrections, stocktaking and reload. A rendered browser check was unavailable for this update.</p><p id="test-note">Earlier version 0.13: 33 automated clinical checks passed, covering patient corrections, allergies, appointment overlaps, dated amendments, prescription review, stock isolation, legacy backup migration and clinical backup validation. Browser checks covered registration, consultations and amendments, appointments, live list filtering, two-medicine prescriptions, review/print view and persistence after reload.</p></details></div></div><div class="maker-signature"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 640" role="img" aria-label="Greylad concentric line G emblem"><g fill="none" stroke="#34363B" stroke-linecap="round" stroke-width="3.1"><path d="M390.48 232.96 A112.00 112.00 0 1 0 431.17 333.65" stroke="#34363B"/><path d="M399.44 226.99 A122.31 122.31 0 1 0 441.40 334.91" stroke="#5A5E66"/><path d="M408.74 221.44 A132.62 132.62 0 1 0 451.64 336.16" stroke="#34363B"/><path d="M418.39 216.32 A142.94 142.94 0 1 0 461.87 337.42" stroke="#34363B"/><path d="M428.36 211.64 A153.25 153.25 0 1 0 472.11 338.68" stroke="#34363B"/><path d="M438.64 207.41 A163.56 163.56 0 1 0 482.34 339.93" stroke="#5A5E66"/><path d="M449.21 203.65 A173.88 173.88 0 1 0 492.58 341.19" stroke="#34363B"/><path d="M460.06 200.38 A184.19 184.19 0 1 0 502.81 342.45" stroke="#34363B"/><path d="M471.15 197.60 A194.50 194.50 0 1 0 513.05 343.70" stroke="#34363B"/><path d="M482.49 195.32 A204.81 204.81 0 1 0 523.29 344.96" stroke="#5A5E66"/><path d="M494.04 193.55 A215.12 215.12 0 1 0 533.52 346.22" stroke="#34363B"/><path d="M505.79 192.31 A225.44 225.44 0 1 0 543.76 347.47" stroke="#34363B"/><path d="M517.72 191.60 A235.75 235.75 0 1 0 553.99 348.73" stroke="#34363B"/><path d="M529.80 191.43 A246.06 246.06 0 1 0 564.23 349.99" stroke="#5A5E66"/><path d="M542.03 191.81 A256.38 256.38 0 1 0 574.46 351.24" stroke="#34363B"/><path d="M554.37 192.75 A266.69 266.69 0 1 0 584.70 352.50" stroke="#34363B"/><path d="M566.81 194.24 A277.00 277.00 0 1 0 594.94 353.76" stroke="#34363B"/></g><path d="M324 320 H562 M324 361 H562" fill="none" stroke="#34363B" stroke-width="4" stroke-linecap="round"/><circle cx="562" cy="361" r="7" fill="#5A5E66"/></svg><span>from Greylad</span></div>`;$('#pharmacy-settings').onsubmit=savePharmacySettings;$('#download-backup').onclick=backup;$('#restore-backup').onclick=()=>$('#restore-file').click();$('#load-demo').onclick=()=>{if(demoMode){go('catalogue');return;}const u=new URL(location.href);u.searchParams.set('demo','1');location.href=u.href;};}
function loadDemo(){try{if(state.medicines.length||state.batches.length||state.sales.length)return;const next=structuredClone(state);const base={generic:'Paracetamol',strength:'500 mg',form:'Tablet',unit:'Tablet',packSize:100,price:100,low:200,shelf:'A2'};const a={...base,id:uuid(),brand:'Demo Brand A'},b={...base,id:uuid(),brand:'Demo Brand B',price:120,shelf:'A3'};next.medicines=[a,b];const year=Number(today().slice(0,4))+2;next.batches=[P.receive(a,{id:uuid(),batch:'DEMO-001',supplier:'Demo supplier',invoice:'SAMPLE-001',date:today(),expiry:year+'-10',packs:10,cost:50000},today()),P.receive(a,{id:uuid(),batch:'DEMO-002',supplier:'Demo supplier',invoice:'SAMPLE-002',date:today(),expiry:year+'-12',packs:5,cost:27500},today()),P.receive(b,{id:uuid(),batch:'DEMO-003',supplier:'Demo supplier',invoice:'SAMPLE-003',date:today(),expiry:year+'-09',packs:1,cost:6000},today())];persist(next);go('catalogue');toast('Sample medicines and batches loaded.');}catch(e){toast(e.message);}}
$('#restore-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;const revision=state.revision;try{if(file.size>20*1024*1024)throw Error('Choose a backup smaller than 20 MB.');const payload=JSON.parse(await file.text()),next=P.validateBackup(payload);if(!confirm(`Restore ${next.medicines.length} medicines, ${next.batches.length} batches and ${next.sales.length} sales and ${next.adjustments.length} adjustments, ${next.suppliers.length} suppliers and ${next.purchaseOrders.length} orders? This replaces the current browser records. Download a backup first if needed.`))return;persist(next,revision);activeInvoice=null;cart=[];saleToken=uuid();go('catalogue');toast('Backup restored successfully.');}catch(err){toast('Restore failed: '+err.message);}finally{e.target.value='';}};
$('.modal-head .close').onclick=()=>$('#dialog').close();$('.modal-footer .close').onclick=()=>$('#dialog').close();$('#close-receipt').onclick=()=>$('#receipt').close();$('#print-receipt').onclick=()=>{document.body.classList.add('printing');window.print();};window.onafterprint=()=>document.body.classList.remove('printing');$('#add').onclick=()=>openForm('medicine');$('#receive').onclick=()=>openForm('receive');$('#search').oninput=()=>{if(['catalogue','batches','sales'].includes(tab))render();else searchLists();};$('#status').onchange=render;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>go(b.dataset.tab));
$('#export').onclick=()=>{const rows=[['Generic','Brand','Strength','Form','Stock unit','Batch','Expiry','Units received','Units remaining','Unit cost UGX','Purchase cost UGX','Supplier','Invoice','Received date'],...state.batches.map(b=>{const m=state.medicines.find(m=>m.id===b.medicineId);return [m.generic,m.brand,m.strength,m.form,m.unit,b.batch,b.expiry,b.units,left(b),b.unitCost,b.cost,b.supplier,b.invoice,b.date]})];const csv=rows.map(r=>r.map(v=>'"'+String(v).replace(/^[=+@-]/,"' $&").replace(/"/g,'""')+'"').join(',')).join('\r\n');download('pharmacy-inventory-'+today()+'.csv','\ufeff'+csv,'text/csv;charset=utf-8');};
let procurementMode='',poLines=[],receivingOrder=null;
function renderProcurement(){const suppliers=state.suppliers,orders=[...state.purchaseOrders].reverse();$('#content').innerHTML=`<div class="section-body"><div class="row-actions"><button id="new-po">＋ New purchase order</button><button class="secondary" id="new-supplier">＋ Add supplier</button><button class="secondary" id="export-po">Export orders CSV</button></div><p>Orders are saved locally and do not contact suppliers or add stock. Receive each delivered medicine and batch against its order; only received stock becomes available.</p><h3>Purchase orders</h3></div>`+table(['ORDER / DATE','SUPPLIER','DELIVERY / STATUS','ESTIMATED / RECEIVED COST','MEDICINES / PACKS'],orders.map(o=>{const progress=P.orderProgress(state,o),supplier=suppliers.find(s=>s.id===o.supplierId);return `<tr><td><strong>${esc(o.id.slice(0,8).toUpperCase())}</strong><small>${esc(o.date)}</small><small class="wrap-cell">${esc(o.note)}</small><button class="link" data-edit-kind="order" data-edit-id="${esc(o.id)}">Edit order</button></td><td>${esc(supplier.name)}</td><td>${esc(o.expectedDate||'No expected date')}<small>${progress.status}</small></td><td>${money(progress.estimated)}<small>Received: ${money(progress.actual)}</small></td><td><details><summary>${o.lines.length} ${o.lines.length===1?'medicine':'medicines'} · ${progress.outstanding} packs outstanding</summary>${progress.lines.map(l=>{const m=state.medicines.find(m=>m.id===l.medicineId);return `<div class="po-line"><strong>${esc(m.brand)}</strong><small>${esc(m.generic)} ${esc(m.strength)} · ${esc(m.form)}</small><small>${l.packs} packs ordered · ${l.received} received · ${l.outstanding} outstanding</small><small>${Packs.factor(l.packSnapshot||m.legacyConfig||Packs.config(m))} ${esc(m.unit)} / ${esc((l.packSnapshot||m.legacyConfig||Packs.config(m)).purchaseUnit)} · Estimated ${money(l.packCost)} / pack</small>${l.outstanding?`<button class="link" data-po="${esc(o.id)}" data-med="${esc(m.id)}">Receive delivery</button>`:''}</div>`}).join('')}</details></td></tr>`}),'No purchase orders yet.')+`<div class="section-body"><h3>Saved suppliers</h3></div>`+table(['SUPPLIER','PHONE / EMAIL','ADDRESS'],suppliers.map(s=>`<tr><td>${esc(s.name)}<br><button class="link" data-edit-kind="supplier" data-edit-id="${esc(s.id)}">Edit</button></td><td>${esc(s.phone||'—')}<small>${esc(s.email||'')}</small></td><td class="wrap-cell">${esc(s.address||'—')}</td></tr>`),'Add your first supplier to prepare an order.');$('#new-po').onclick=()=>openProcurement('order');$('#new-supplier').onclick=()=>openProcurement('supplier');$('#export-po').onclick=()=>csvFile('purchase-orders-'+today()+'.csv',[['Order','Date','Supplier','Expected delivery','Status','Brand','Generic','Strength','Form','Stock unit','Units per pack','Ordered packs','Received packs','Outstanding packs','Estimated cost per pack UGX'],...orders.flatMap(o=>P.orderProgress(state,o).lines.map(l=>{const m=state.medicines.find(m=>m.id===l.medicineId);return [o.id,o.date,suppliers.find(s=>s.id===o.supplierId).name,o.expectedDate,P.orderProgress(state,o).status,m.brand,m.generic,m.strength,m.form,m.unit,m.packSize,l.packs,l.received,l.outstanding,l.packCost]}))]);document.querySelectorAll('[data-po]').forEach(b=>b.onclick=()=>openOrderDelivery(b.dataset.po,b.dataset.med));}
function openProcurement(kind){editing=null;procurementMode=kind;poLines=[];formRevision=state.revision;$('#proc-form').reset();$('#proc-error').textContent='';$('#proc-title').textContent=kind==='supplier'?'Add supplier':'New purchase order';$('#proc-fields').innerHTML=kind==='supplier'?field('Supplier name *','name','text','','required maxlength="100"')+field('Phone','phone','tel','','maxlength="100"')+field('Email','email','email','','maxlength="200"')+field('Address','address','text','','maxlength="300"'):`<label>Supplier *<select name="supplierId" required><option value="">Select supplier</option>${state.suppliers.map(s=>`<option value="${esc(s.id)}" ${s.status==='suspended'?'disabled':''}>${esc(s.name)}${s.status==='suspended'?' (on hold)':''}</option>`).join('')}</select></label>`+field('Order date *','date','date',today(),'required max="'+today()+'"')+field('Expected delivery','expectedDate','date','','min="'+today()+'"')+field('Order note','note','text','','maxlength="500"')+`<div class="full po-builder"><label>Medicine / brand<select id="po-med"><option value="">Select medicine</option>${state.medicines.map(m=>`<option value="${esc(m.id)}">${esc(m.brand)} / ${esc(m.generic)} ${esc(m.strength)} · ${esc(m.form)} (${m.packSize} ${esc(m.unit)} / ${esc(Packs.config(m).purchaseUnit)})</option>`).join('')}</select></label><label>Packs to order<input id="po-packs" type="number" min="1" step="1"></label><label>Estimated purchase cost per pack (UGX)<input id="po-cost" type="number" min="0.01" step="0.01"></label><button type="button" id="po-add">Add medicine to order</button><div id="po-lines"></div><p class="note">Enter purchase cost per pack, not selling price per stock unit. Actual invoice cost is entered when stock arrives.</p></div>`;if(kind==='order'){$('#po-add').onclick=()=>{try{const medicineId=$('#po-med').value,packs=Number($('#po-packs').value),packCost=Number($('#po-cost').value);if(!medicineId||!Number.isSafeInteger(packs)||packs<1||!Number.isFinite(packCost)||packCost<=0||packCost>1e12||Math.abs(packCost*100-Math.round(packCost*100))>.001)throw Error('Choose a medicine, whole packs and a positive pack cost with up to two decimal places.');if(poLines.some(l=>l.medicineId===medicineId))throw Error('This medicine is already in the order. Remove the line to change it.');poLines.push({medicineId,packs,packCost,packSnapshot:Packs.config(state.medicines.find(m=>m.id===medicineId))});$('#proc-error').textContent='';drawPoLines();}catch(e){$('#proc-error').textContent=e.message;}};drawPoLines();}$('#proc-dialog').showModal();}
function drawPoLines(){$('#po-lines').innerHTML=poLines.map((l,i)=>{const m=state.medicines.find(m=>m.id===l.medicineId);return `<div class="cart-row"><span>${esc(m.brand)} / ${esc(m.generic)} ${esc(m.strength)}<small>${l.packs} ${esc((l.packSnapshot||m.legacyConfig||Packs.config(m)).purchaseUnit)} × ${money(l.packCost)} = ${money(l.packs*l.packCost)}</small></span><button type="button" class="link" data-po-remove="${i}">Remove</button></div>`}).join('')+`<p>Estimated order total: <b>${money(poLines.reduce((n,l)=>n+l.packs*l.packCost,0))}</b></p>`;document.querySelectorAll('[data-po-remove]').forEach(b=>b.onclick=()=>{poLines.splice(Number(b.dataset.poRemove),1);drawPoLines();});}
$('#proc-form').onsubmit=e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));for(const k in d)d[k]=d[k].trim();let next;const id=uuid();if(editing){const patch=procurementMode==='supplier'?{name:d.name,phone:d.phone,email:d.email,address:d.address}:{supplierId:d.supplierId||state.purchaseOrders.find(o=>o.id===editing.id).supplierId,date:d.date,expectedDate:d.expectedDate,note:d.note,lines:poLines};next=P.editRecord(state,editing.kind,editing.id,patch,editActor(d),today(),new Date().toISOString(),id);}else{next=structuredClone(state);if(procurementMode==='supplier')next.suppliers.push(P.validateSupplier({...d,id},state.suppliers));else next.purchaseOrders.push(P.purchaseOrder(state,{...d,id,lines:poLines},today()));next.events.push({at:new Date().toISOString(),id,action:procurementMode==='supplier'?'Supplier added':'Purchase order created'});}persist(next,formRevision);$('#proc-dialog').close();const edited=!!editing;editing=null;render();toast(edited?'Correction saved with edit history.':procurementMode==='supplier'?'Supplier saved.':'Purchase order saved locally. No stock added yet.');}catch(e){$('#proc-error').textContent=e.message;}};
$('#proc-close').onclick=()=>$('#proc-dialog').close();$('#proc-cancel').onclick=()=>$('#proc-dialog').close();
function openOrderDelivery(orderId,medicineId){openForm('receive',medicineId);receivingOrder={orderId,medicineId};const o=state.purchaseOrders.find(o=>o.id===orderId),supplier=state.suppliers.find(s=>s.id===o.supplierId),line=P.orderProgress(state,o).lines.find(l=>l.medicineId===medicineId);$('#form-title').textContent='Receive purchase order '+o.id.slice(0,8).toUpperCase();$('#form [name="medicineId"]').disabled=true;$('#form [name="supplierId"]').value=supplier.id;$('#form [name="supplierId"]').disabled=true;$('#form [name="packs"]').max=line.outstanding;$('#form [name="date"]').min=o.date;$('#form [name="packs"]').value=line.outstanding;$('#form [name="cost"]').value='';calculate();}

let editing=null;
function editorFields(){return `<div class="full edit-notice">Changes are saved with the editor, date and reason.</div>`+field('Editor name *','editorName','text','','required maxlength="100"')+`<label>Editor role *<select name="editorRole" required><option value="">Select role</option><option>Owner</option><option>Manager</option><option>Pharmacist</option><option>Stock clerk</option><option>Stock manager</option></select></label>`+field('Reason for correction *','editReason','text','','required maxlength="500"');}
function editActor(d){return {name:d.editorName,role:d.editorRole,reason:d.editReason};}
function openEdit(kind,id){const record=state[kind==='medicine'?'medicines':kind==='supplier'?'suppliers':'purchaseOrders'].find(x=>x.id===id);if(kind==='order'||kind==='supplier'){openProcurement(kind==='order'?'order':'supplier');editing={kind,id};$('#proc-title').textContent=kind==='order'?'Correct purchase order':'Correct supplier';const form=$('#proc-form');for(const [k,v] of Object.entries(record)){const el=form.elements.namedItem(k);if(el)el.value=v;}if(kind==='order'){poLines=structuredClone(record.lines);drawPoLines();const received=state.batches.some(b=>b.purchaseOrderId===id);if(received){form.elements.namedItem('date').readOnly=true;form.elements.namedItem('supplierId').disabled=true;}form.elements.namedItem('expectedDate').removeAttribute('min');}else if(state.purchaseOrders.some(o=>o.supplierId===id)||state.batches.some(b=>b.supplierId===id))form.elements.namedItem('name').readOnly=true;$('#proc-fields').insertAdjacentHTML('beforeend',editorFields());return;}
editing={kind,id};formRevision=state.revision;const used=state.batches.some(b=>b.medicineId===id)||state.purchaseOrders.some(o=>o.lines.some(l=>l.medicineId===id));$('#edit-title').textContent='Edit medicine';$('#edit-fields').innerHTML=['generic','brand','strength','form','unit'].map(k=>field(k[0].toUpperCase()+k.slice(1)+' *',k,'text',record[k],'required maxlength="100" '+'')).join('')+field('Units per purchase pack *','packSize','number',record.packSize,'required min="1" step="1"')+field('Selling price / smallest unit (UGX) *','price','number',record.price,'required min="0" max="1000000000000" step="0.01"')+field('Low-stock level *','low','number',record.low,'required min="0" step="1"')+field('Shelf','shelf','text',record.shelf||'','maxlength="40"')+`<p class="note full">${used?'The smallest unit label can be corrected with confirmation. Existing quantities are not converted or multiplied. Correct descriptions with a reason; use a separate product for a different medicine. Pack changes apply to future receipts and orders. Existing batch pack sizes and saved receipts are preserved.':'Product identity can be corrected before stock or orders exist.'}</p>`+editorFields();mountPackEditor($('#edit-fields'),record,used);$('#edit-error').textContent='';$('#edit-dialog').showModal();}
$('#edit-form').onsubmit=e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target)),patch={};for(const k of ['generic','brand','strength','form','unit','shelf'])patch[k]=d[k].trim();for(const k of ['packSize','price','low'])patch[k]=Number(d[k]);patch.packConfig=readPackEditor($('#edit-fields'),d);patch.unit=patch.packConfig.baseUnit;patch.packSize=Packs.factor(patch.packConfig);const prior=state.medicines.find(m=>m.id===editing.id);if(prior.unit!==patch.unit){if(!confirm('Correct the unit label from '+prior.unit+' to '+patch.unit+'? Existing quantities and purchase costs stay exactly the same. This does NOT convert tablets into bottles or packs. Use packaging levels for those conversions. Saved receipts keep their original labels.'))return;patch.unitCorrectionConfirmed=true;}const next=P.editRecord(state,editing.kind,editing.id,patch,editActor(d),today(),new Date().toISOString(),uuid());persist(next,formRevision);$('#edit-dialog').close();editing=null;render();toast('Correction saved with edit history.');}catch(e){$('#edit-error').textContent=e.message;focusPackError($('#edit-fields'));}};
$('#edit-close').onclick=()=>$('#edit-dialog').close();$('#edit-cancel').onclick=()=>$('#edit-dialog').close();
function renderHistory(){const rows=[...(state.editHistory||[])].reverse();$('#content').innerHTML=`<div class="section-body"><p>Each correction keeps the previous and revised values, editor name, declared role, time and reason. This is a local change log, not an authenticated or tamper-proof audit trail.</p><button class="secondary" id="history-export">Export edit history CSV</button></div>`+table(['WHEN / WHO','RECORD','REASON','CHANGES'],rows.map(e=>`<tr><td>${esc(new Date(e.at).toLocaleString('en-GB',{timeZone:'Africa/Kampala'}))} EAT<small>${esc(e.name)} · ${esc(e.role)}</small></td><td>${esc(e.kind)}<small>${esc(e.before.brand||e.before.name||e.recordId.slice(0,8).toUpperCase())}</small></td><td class="wrap-cell">${esc(e.reason)}</td><td class="wrap-cell"><details><summary>View previous and revised values</summary>${Object.keys(e.after).filter(k=>JSON.stringify(e.before[k])!==JSON.stringify(e.after[k])).map(k=>`<p><b>${esc(k)}</b><br>Before: ${esc(JSON.stringify(e.before[k]))}<br>After: ${esc(JSON.stringify(e.after[k]))}</p>`).join('')}</details></td></tr>`),'No corrections recorded yet.');$('#history-export').onclick=()=>csvFile('edit-history-'+today()+'.csv',[['Time UTC','Editor','Declared role','Record type','Record ID','Reason','Before','After'],...rows.map(e=>[e.at,e.name,e.role,e.kind,e.recordId,e.reason,JSON.stringify(e.before),JSON.stringify(e.after)])]);}
function searchLists(){if(['catalogue','sales'].includes(tab))return;const q=P.norm($('#search').value);document.querySelectorAll('#content tbody tr').forEach(row=>{row.hidden=!!q&&!P.norm(row.textContent+' '+(row.closest('.brand-group')?.querySelector('h3')?.textContent||'')).includes(q);});}
function enhanceSelectors(){document.querySelectorAll('#fields select[name="medicineId"],#fields select[name="supplierId"],#proc-fields select[name="supplierId"],#po-med,#sale-medicine,#adjust-batch,#group-filter,#block-target').forEach(select=>{if(select.dataset.searchReady||select.disabled)return;select.dataset.searchReady='1';const options=[...select.options].map(o=>({value:o.value,text:o.textContent})),required=select.required,wrap=document.createElement('div'),input=document.createElement('input'),list=document.createElement('div');wrap.className='combo';input.type='text';input.autocomplete='off';input.placeholder='Search and select…';input.setAttribute('role','combobox');input.setAttribute('aria-autocomplete','list');input.setAttribute('aria-expanded','false');input.setAttribute('aria-label',select.name==='supplierId'?'Search suppliers':'Search medicines or batches');list.id='options-'+uuid();list.className='combo-options';list.setAttribute('role','listbox');list.hidden=true;input.setAttribute('aria-controls',list.id);input.required=required;const initial=options.find(o=>o.value===select.value);input.value=initial?.value?initial.text:'';select.required=false;select.hidden=true;select.before(wrap);wrap.append(input,list);let matches=[],active=-1;
const close=()=>{list.hidden=true;input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');};const validate=()=>input.setCustomValidity(input.value&&!select.value?'Choose a result from the list.':'');const choose=o=>{select.value=o.value;input.value=o.value?o.text:'';validate();close();select.dispatchEvent(new Event('change',{bubbles:true}));select.dispatchEvent(new Event('input',{bubbles:true}));};
const draw=q=>{matches=options.filter(o=>(o.value||!required)&&P.norm(o.text).includes(P.norm(q)));active=-1;list.replaceChildren();for(const [i,o] of matches.entries()){const button=document.createElement('button');button.type='button';button.id=list.id+'-'+i;button.setAttribute('role','option');button.textContent=o.text;button.onpointerdown=e=>e.preventDefault();button.onmousedown=e=>e.preventDefault();button.onclick=()=>choose(o);list.append(button);}if(!matches.length){const msg=document.createElement('div');msg.className='combo-empty';msg.textContent='No matches. Add a record first.';list.append(msg);}list.hidden=false;input.setAttribute('aria-expanded','true');};input.onfocus=()=>draw('');input.oninput=()=>{select.value='';validate();draw(input.value);select.dispatchEvent(new Event('change',{bubbles:true}));};input.onblur=()=>close();input.onkeydown=e=>{if(e.key==='Escape'){if(!list.hidden){e.preventDefault();e.stopPropagation();}close();return;}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(list.hidden)draw(input.value);active=active<0?(e.key==='ArrowDown'?0:matches.length-1):Math.max(0,Math.min(matches.length-1,active+(e.key==='ArrowDown'?1:-1)));[...list.querySelectorAll('button')].forEach((b,i)=>b.setAttribute('aria-selected',String(i===active)));if(active>=0&&matches[active]){input.setAttribute('aria-activedescendant',list.id+'-'+active);list.children[active].scrollIntoView?.({block:'nearest'});}}if(e.key==='Enter'&&!list.hidden){e.preventDefault();if(matches[active>=0?active:0])choose(matches[active>=0?active:0]);}};validate();});}
new MutationObserver(()=>{enhanceSelectors();searchLists();}).observe($('#content'),{childList:true,subtree:true});
new MutationObserver(enhanceSelectors).observe($('#fields'),{childList:true,subtree:true});
new MutationObserver(enhanceSelectors).observe($('#proc-fields'),{childList:true,subtree:true});
new MutationObserver(enhanceSelectors).observe($('#adjust-fields'),{childList:true,subtree:true});

function renderAlerts(){$('#content').innerHTML=`<div class="section-body"><div class="compare-controls"><label>Expiry window<select id="alert-window"><option value="30">Next 30 days</option><option value="60">Next 60 days</option><option value="90" selected>Next 90 days</option><option value="180">Next 180 days</option></select></label><button class="secondary" id="alert-export">Export stock alerts CSV</button><button class="secondary" id="alert-orders">New purchase order</button><button class="secondary" id="alert-adjust">Record stock adjustment</button></div><p>Available stock excludes expired and quarantined batches. On-order quantities are unreceived packs converted to stock units; delivery dates and availability are not guaranteed. Expiry uses the last day of the labelled month.</p><div id="alert-summary" class="stats"></div></div><div id="alert-tables"></div>`;$('#alert-window').onchange=updateAlerts;$('#alert-orders').onclick=()=>go('procurement');$('#alert-adjust').onclick=()=>{go('adjustments');openAdjustment();};$('#alert-export').onclick=()=>{const r=P.stockAlerts(state,today(),Number($('#alert-window').value)),q=P.norm($('#search').value);const matches=values=>!q||P.norm(values.join(' ')).includes(q);csvFile('stock-alerts-'+today()+'.csv',[['Alert','Shelf','Brand','Generic','Strength','Form','Stock unit','Batch','Expiry','Available or batch units','On order units','Low-stock level','Batch stock value UGX'],...r.stock.map(x=>[x.available===0?'Out of stock':'Low stock',x.medicine.shelf||'Unassigned',x.medicine.brand,x.medicine.generic,x.medicine.strength,x.medicine.form,x.medicine.unit,'','',x.available,x.incoming,x.medicine.low,'']).filter(matches),...r.expiry.map(x=>[x.status,x.medicine.shelf||'Unassigned',x.medicine.brand,x.medicine.generic,x.medicine.strength,x.medicine.form,x.medicine.unit,x.batch.batch,x.batch.expiry,x.units,'','',x.value]).filter(matches)]);};updateAlerts();}
function updateAlerts(){const r=P.stockAlerts(state,today(),Number($('#alert-window').value)),out=r.stock.filter(x=>x.available===0).length,expired=r.expiry.filter(x=>x.status==='Expired'),soon=r.expiry.filter(x=>x.status==='Expiring soon');$('#alert-summary').innerHTML=[['Out of stock',out,'medicine products'],['Low stock',r.stock.length-out,'products with some usable stock'],['Expiring soon',soon.length,'available batches in selected window'],['Expired stock',expired.length,'batches still on hand']].map(x=>`<div class="stat"><label>${x[0]}</label><strong>${x[1]}</strong><span>${x[2]}</span></div>`).join('');$('#alert-tables').innerHTML=`<div class="section-body"><h3>Stock to review</h3><p>Low-stock levels are alerts, not suggested order quantities. Check expected demand and open orders before buying.</p></div>`+table(['BRAND / GENERIC','SHELF','ALERT','AVAILABLE','LOW-STOCK LEVEL','ON ORDER'],r.stock.map(x=>`<tr><td><strong>${esc(x.medicine.brand)}</strong><small>${esc(x.medicine.generic)} ${esc(x.medicine.strength)} · ${esc(x.medicine.form)}</small></td><td>${esc(x.medicine.shelf||'Unassigned')}</td><td><span class="pill ${x.available===0?'danger':'warn'}">${x.available===0?'Out of stock':'Low stock'}</span></td><td>${x.available} ${esc(x.medicine.unit)}</td><td>${x.medicine.low} ${esc(x.medicine.unit)}</td><td>${x.incoming} ${esc(x.medicine.unit)}</td></tr>`),'No low-stock or out-of-stock medicines.')+`<div class="section-body"><h3>Expiry and blocked stock</h3><p>Expired and quarantined stock is blocked at checkout. Quarantined batches appear regardless of the expiry window. Expired remaining stock is included in the stock-loss summary at purchase cost. A temporary hold remains stock on hand, not a loss, unless written off.</p></div>`+table(['BRAND / GENERIC','SHELF','BATCH / EXPIRY','STATUS','ON HAND','PURCHASE VALUE'],r.expiry.map(x=>`<tr><td><strong>${esc(x.medicine.brand)}</strong><small>${esc(x.medicine.generic)} ${esc(x.medicine.strength)} · ${esc(x.medicine.form)}</small></td><td>${esc(x.medicine.shelf||'Unassigned')}</td><td>${esc(x.batch.batch)}<small>${esc(x.batch.expiry)}</small></td><td><span class="pill ${x.status==='Expired'?'danger':'warn'}">${x.status}</span><small>${x.days<0?Math.abs(x.days)+' days past month end':x.days+' days to month end'}</small></td><td>${x.units} ${esc(x.medicine.unit)}</td><td>${money(x.value)}</td></tr>`),'No expiry or blocked-stock alerts.');searchLists();}

let employeeEditing=null;
function renderEmployees(){$('#content').innerHTML=`<div class="section-body"><button id="add-employee">＋ Add employee</button><p>Employee directory only. Active status and job titles do not grant system permissions or create login accounts.</p></div>`+table(['STAFF CODE / NAME','JOB / STATUS','CONTACT','START DATE',''],state.employees.map(e=>`<tr><td><strong>${esc(e.name)}</strong><small>${esc(e.code)}</small></td><td>${esc(e.job)}<small>${esc(e.status)}</small></td><td>${esc(e.phone||'—')}<small>${esc(e.email)}</small></td><td>${esc(e.startDate||'—')}</td><td><button class="link" data-employee="${esc(e.id)}">Edit</button></td></tr>`),'No employees recorded.');$('#add-employee').onclick=()=>openEmployee();document.querySelectorAll('[data-employee]').forEach(b=>b.onclick=()=>openEmployee(b.dataset.employee));}
function openEmployee(id){employeeEditing=id||null;formRevision=state.revision;const e=state.employees.find(e=>e.id===id)||{name:'',code:'',job:'',phone:'',email:'',startDate:'',status:'Active'};$('#employee-title').textContent=id?'Edit employee':'Add employee';$('#employee-fields').innerHTML=field('Full name *','name','text',e.name,'required maxlength="100"')+field('Staff code *','code','text',e.code,'required maxlength="40"')+field('Job title *','job','text',e.job,'required maxlength="100"')+field('Phone','phone','tel',e.phone,'maxlength="200"')+field('Email','email','email',e.email,'maxlength="200"')+field('Start date','startDate','date',e.startDate)+`<label>Status<select name="status"><option ${e.status==='Active'?'selected':''}>Active</option><option ${e.status==='Inactive'?'selected':''}>Inactive</option></select></label>`+editorFields();$('#employee-error').textContent='';$('#employee-dialog').showModal();}
$('#employee-form').onsubmit=e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target)),patch={};for(const k of ['name','code','job','phone','email','startDate','status'])patch[k]=d[k].trim();const actor=editActor(d),at=new Date().toISOString();let next;if(employeeEditing)next=P.editRecord(state,'employee',employeeEditing,patch,actor,today(),at,uuid());else{if(!actor.name.trim()||!actor.reason.trim()||!['Owner','Manager','Admin'].includes(actor.role))throw Error('Enter recorder name, Owner or Manager role and reason.');next=structuredClone(state);next.employees.push(P.validateEmployee({...patch,id:uuid(),createdAt:at,createdBy:actor.name.trim()},state.employees));next.events.push({action:'Employee added',at,name:actor.name.trim(),role:actor.role,reason:actor.reason.trim()});}persist(next,formRevision);$('#employee-dialog').close();render();toast('Employee details saved.');}catch(e){$('#employee-error').textContent=e.message;}};
$('#employee-close').onclick=()=>$('#employee-dialog').close();$('#employee-cancel').onclick=()=>$('#employee-dialog').close();
function renderShelves(){$('#content').innerHTML=`<div class="section-body"><div class="compare-controls"><label>Sort batches by<select id="shelf-sort"><option value="received">First received</option><option value="expiry">Earliest expiry</option></select></label></div><p>Shelf locations come from the medicine catalogue. Use Medicines → Edit to assign or correct a shelf. Each medicine currently has one shelf for all its batches. First received shows receipt order; earliest expiry identifies usable stock with the nearest expiry.</p></div><div id="shelf-tables"></div>`;$('#shelf-sort').onchange=updateShelves;updateShelves();}
function updateShelves(){const rows=P.shelfStock(state,today());if($('#shelf-sort').value==='expiry')rows.sort((a,b)=>P.norm(a.shelf).localeCompare(P.norm(b.shelf))||a.batch.expiry.localeCompare(b.batch.expiry)||a.batch.date.localeCompare(b.batch.date));const groups=[...new Set(rows.map(r=>r.shelf))];$('#shelf-tables').innerHTML=groups.length?groups.map(shelf=>`<div class="brand-group"><h3>Shelf ${esc(shelf)}</h3>`+table(['BRAND / GENERIC','BATCH','RECEIVED','EXPIRY','ON HAND','STOCK ORDER / STATUS'],rows.filter(r=>r.shelf===shelf).map(r=>{const same=rows.filter(x=>x.medicine.id===r.medicine.id),usable=same.filter(x=>x.usable),first=same.map(x=>x.batch.date).sort()[0],earliest=usable.map(x=>x.batch.expiry).sort()[0];return `<tr><td><strong>${esc(r.medicine.brand)}</strong><small>${esc(r.medicine.generic)} ${esc(r.medicine.strength)} · ${esc(r.medicine.form)}</small></td><td>${esc(r.batch.batch)}</td><td>${esc(r.batch.date)}</td><td>${esc(r.batch.expiry)}<small>${r.days<0?'Expired':r.days<=90?'Within 90 days':''}</small></td><td>${r.qty} ${esc(r.medicine.unit)}</td><td>${r.batch.date===first?'<small>First received (remaining stock)</small>':''}${r.usable&&r.batch.expiry===earliest?'<small>Earliest expiry (usable stock)</small>':''}<span class="pill ${r.usable?'':'danger'}">${P.expired(r.batch,today())?'Expired · blocked':r.batch.status==='quarantined'?'Quarantined':'Available'}</span></td></tr>`}))+`</div>`).join(''):'<div class="empty">No stock on shelves yet. Receive stock first.</div>';}

function refreshBatchChoices(){const id=$('#sale-medicine').value,previous=$('#sale-batch').value,m=state.medicines.find(m=>m.id===id),batches=state.batches.filter(b=>b.medicineId===id&&b.date<=today()&&!P.expired(b,today())&&!['quarantined','writtenoff'].includes(b.status)&&P.basketRemaining(state,cart,b)>0).sort((a,b)=>a.expiry.localeCompare(b.expiry)||a.date.localeCompare(b.date));$('#sale-batch').innerHTML=batches.length?batches.map(b=>`<option value="${esc(b.id)}">${esc(b.batch)} · Exp ${esc(b.expiry)} · ${P.basketRemaining(state,cart,b)} left to add (${left(b)} on hand)</option>`).join(''):'<option value="">No units left to add</option>';if(batches.some(b=>b.id===previous))$('#sale-batch').value=previous;const b=state.batches.find(b=>b.id===$('#sale-batch').value);$('#sale-qty').max=b?P.basketRemaining(state,cart,b):0;$('#batch-hint').textContent=m?`${m.brand}: ${available(m)} ${m.unit} on hand and saleable · ${cart.filter(l=>state.batches.find(b=>b.id===l.batchId)?.medicineId===m.id).reduce((n,l)=>n+l.qty,0)} in basket · ${money(m.price)} each`:'Choose a medicine.';syncSaleUnit();}
function refreshStockChoices(){if(!$('#sale-medicine'))return;const select=$('#sale-medicine'),selected=select.value;select.innerHTML='<option value="">Select medicine</option>'+state.medicines.map(m=>{const reserved=cart.filter(l=>state.batches.find(b=>b.id===l.batchId)?.medicineId===m.id).reduce((n,l)=>n+l.qty,0);return `<option value="${esc(m.id)}">${esc(m.generic)} ${esc(m.strength)} · ${esc(m.brand)} (${Math.max(0,available(m)-reserved)} ${esc(m.unit)} left to add; ${reserved} in basket)</option>`}).join('');select.value=selected;if(select.previousElementSibling?.classList.contains('combo'))select.previousElementSibling.remove();delete select.dataset.searchReady;enhanceSelectors();refreshBatchChoices();}
function pharmacySettingsHTML(){return `<div class="section-body"><h2>Pharmacy identity</h2><form id="pharmacy-settings" class="fields">${field('Pharmacy name *','pharmacyName','text',state.settings.pharmacyName,'required maxlength="80"')}${field('Recorded by *','recordedBy','text','','required maxlength="100"')}<button type="submit">Save pharmacy name</button></form><p id="settings-error" role="alert"></p><p>Receipt format: PHARMACYNAME26102026/G000001. The sequence runs across dates in this workspace. Saved receipts keep their original name and number. Changing this offline name is recorded locally; email-code verification will require the online account system. Restoring an older backup can reuse numbers issued after that backup, so retain the latest backup.</p></div>`;}
function savePharmacySettings(e){e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target)),name=d.pharmacyName.trim();if(!name||name.length>80||!/[A-Za-z0-9]/.test(name)||!d.recordedBy.trim())throw Error('Enter a pharmacy name containing letters or numbers and who recorded it.');const next=structuredClone(state);next.events.push({action:'Pharmacy name changed',before:state.settings.pharmacyName,after:name,name:d.recordedBy.trim(),at:new Date().toISOString()});next.settings.pharmacyName=name;persist(next);render();toast('Pharmacy name saved. Existing receipts unchanged.');}catch(e){$('#settings-error').textContent=e.message;}}
function lossPanel(){const r=P.lossSummary(state,today()),gp=state.sales.reduce((n,s)=>n+s.profit,0);return `<div class="section-body"><h3>Stock losses · all recorded history, assessed today</h3><div class="stats">${[['Recorded write-offs',r.writtenOff],['Expired stock still on hand',r.expiredOnHand],['Temporary holds at cost',r.held],['Sales profit less stock losses',gp-r.total]].map(([l,v])=>`<div class="stat"><label>${l}</label><strong>${money(v)}</strong></div>`).join('')}</div><p>Expired remaining stock is treated as a loss at purchase cost, assuming no supplier credit or recovery. Recording its write-off transfers the same value into recorded write-offs without counting it twice. Temporary holds are excluded from losses. Stocktake shortages are included. Standalone physical count corrections, stock surpluses, supplier returns, operating expenses, taxes and recoveries are excluded. Surpluses do not reverse previously recorded losses. This all-history summary is separate from the date-filtered sales report.</p></div>`;}
function renderBlocks(){const held=state.batches.filter(b=>b.status==='quarantined'||b.status==='writtenoff'),suspended=state.suppliers.filter(s=>s.status==='suspended');$('#content').innerHTML=`<div class="section-body"><div class="row-actions"><button id="block-batch">Hold / release / write off stock</button><button class="secondary" id="block-supplier">Suspend / reinstate supplier</button></div><p>Batch holds and supplier suspensions are independent. A batch hold prevents sale but keeps stock on hand at purchase cost. A permanent write-off removes all remaining units in the selected receipt batch and creates a stock adjustment. It does not confirm physical destruction. If the same batch was received several times, review each receipt separately.</p><h3>Held and written-off stock</h3></div>`+table(['BRAND / GENERIC','BATCH / SUPPLIER','SHELF','STATUS','ON HAND'],held.map(b=>{const m=state.medicines.find(m=>m.id===b.medicineId);return `<tr><td>${esc(m.brand)}<small>${esc(m.generic)} ${esc(m.strength)}</small></td><td>${esc(b.batch)}<small>${esc(b.supplier)} · ${esc(b.invoice)}</small></td><td>${esc(m.shelf||'Unassigned')}</td><td>${b.status==='writtenoff'?'Permanent write-off':'Temporary hold'}${P.expired(b,today())?' · expired':''}</td><td>${left(b)} ${esc(m.unit)}</td></tr>`}),'No held or written-off stock.')+`<div class="section-body"><h3>Suspended suppliers</h3><p>New orders and deliveries are blocked until reinstated. Existing stock from these suppliers remains unchanged.</p></div>`+table(['SUPPLIER','PHONE'],suspended.map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.phone)}</td></tr>`),'No suspended suppliers.')+lossPanel()+lossDetailTable()+`<div class="section-body"><h3>Hold and release history</h3></div>`+table(['WHEN / WHO','RECORD','ACTION','REASON','WRITE-OFF VALUE'],[...state.blockHistory].reverse().map(e=>{const r=(e.kind==='batch'?state.batches:state.suppliers).find(r=>r.id===e.targetId);return `<tr><td>${esc(new Date(e.at).toLocaleString('en-GB',{timeZone:'Africa/Kampala'}))} EAT<small>${esc(e.name)} · ${esc(e.role)}</small></td><td>${esc(r?.batch||r?.name)}<small>${esc(e.kind)}</small></td><td>${esc(e.action)}</td><td class="wrap-cell">${esc(e.reason)}</td><td>${money(e.value)}</td></tr>`}),'No block actions recorded.');$('#block-batch').onclick=()=>openBlock('batch');$('#block-supplier').onclick=()=>openBlock('supplier');}
let blockKind='batch';
function openBlock(kind){blockKind=kind;formRevision=state.revision;$('#block-form').reset();$('#block-error').textContent='';$('#block-fields').innerHTML=`<label class="full">${kind==='batch'?'Medicine / brand / receipt batch':'Supplier'}<select id="block-target" required><option value="">Select record</option>${(kind==='batch'?state.batches.filter(b=>left(b)>0&&b.status!=='writtenoff'):state.suppliers).map(r=>{const m=state.medicines.find(m=>m.id===r.medicineId);return `<option value="${esc(r.id)}">${esc(kind==='batch'?m.brand+' / '+m.generic+' '+m.strength+' · '+r.batch+' · '+r.supplier+' · '+r.invoice:r.name)} (${esc(r.status||'available')})</option>`}).join('')}</select></label><label>Action<select id="block-action"><option value="hold">${kind==='batch'?'Temporary hold':'Suspend supplier'}</option><option value="release">${kind==='batch'?'Release temporary hold':'Reinstate supplier'}</option>${kind==='batch'?'<option value="writeoff">Permanent block and write-off</option>':''}</select></label>`+editorFields()+`<p class="note full">Releasing a hold never makes expired stock saleable. Permanent write-offs cannot be released. Account preview automatically supplies the recorder identity.</p>`;$('#block-dialog').showModal();enhanceSelectors();}
$('#block-form').onsubmit=e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target)),input={kind:blockKind,targetId:$('#block-target').value,action:$('#block-action').value,name:d.editorName,role:d.editorRole,reason:d.editReason};if(input.action==='writeoff'&&!confirm('Permanently write off all remaining stock in this receipt batch? This records a loss and cannot be released.'))return;const next=P.blockAction(state,input,today(),new Date().toISOString(),uuid());persist(next,formRevision);$('#block-dialog').close();render();toast('Action recorded.');}catch(e){$('#block-error').textContent=e.message;}};
$('#block-close').onclick=()=>$('#block-dialog').close();$('#block-cancel').onclick=()=>$('#block-dialog').close();

let activeInvoice=null,invoiceAction=null;
function renderInvoices(){const invoices=[...state.invoices].reverse();$('#content').innerHTML=`<div class="section-body"><button id="invoice-start">＋ Prepare invoice in checkout</button><p>Build a basket in Checkout, then choose Save unpaid invoice. Stock is checked again at payment and is not reserved or deducted by an unpaid invoice. Full payment only; goods are issued when the sale is completed. This is not a tax invoice.</p></div>`+table(['INVOICE / DATE','CUSTOMER / DUE','ITEMS','TOTAL','STATUS','ACTIONS'],invoices.map(i=>`<tr><td>${esc(i.invoiceNo)}<small>${esc(i.date)}</small></td><td>${esc(i.customer)}<small>Due ${esc(i.due)}</small></td><td>${saleCount(i)}</td><td>${money(i.total)}</td><td>${esc(i.status)}${i.status==='Unpaid'&&i.due<today()?' · overdue':''}<small>${i.status==='Cancelled'?esc(i.cancelledBy+' · '+i.cancelReason):'Created by '+esc(i.recordedBy)}</small></td><td><button class="link" data-view-invoice="${esc(i.id)}">View / print</button>${i.status==='Unpaid'?`<button class="link" data-pay-invoice="${esc(i.id)}">Take payment</button><button class="link" data-cancel-invoice="${esc(i.id)}">Cancel</button>`:i.status==='Paid'?`<button class="link" data-receipt="${esc(i.saleId)}">Receipt</button>`:''}</td></tr>`),'No invoices yet.');$('#invoice-start').onclick=()=>go('checkout');document.querySelectorAll('[data-view-invoice]').forEach(b=>b.onclick=()=>showInvoice(b.dataset.viewInvoice));document.querySelectorAll('[data-pay-invoice]').forEach(b=>b.onclick=()=>{if(cart.length&&!confirm('Replace the current unsaved basket with this invoice?'))return;const i=state.invoices.find(i=>i.id===b.dataset.payInvoice);activeInvoice=i.id;cart=i.lines.map(l=>({...l}));saleToken=uuid();go('checkout');});document.querySelectorAll('[data-cancel-invoice]').forEach(b=>b.onclick=()=>openInvoiceForm(b.dataset.cancelInvoice));}
function openInvoiceForm(cancelId){invoiceAction=cancelId||null;formRevision=state.revision;$('#invoice-form').reset();$('#invoice-error').textContent='';$('#invoice-title').textContent=cancelId?'Cancel unpaid invoice':'Save unpaid invoice';$('#invoice-fields').innerHTML=cancelId?field('Recorded by *','name','text','','required maxlength="100"')+field('Reason *','reason','text','','required maxlength="500"'):field('Customer / organisation *','customer','text','','required maxlength="100"')+field('Due date *','due','date',today(),'required min="'+today()+'"')+field('Recorded by *','recordedBy','text','','required maxlength="100"');$('#invoice-dialog').showModal();}
function invoiceCheckoutControls(){const active=state.invoices.find(i=>i.id===activeInvoice);const box=$('#complete-sale').parentElement;const section=document.createElement('div');section.className='invoice-controls';section.innerHTML=active?`<p>Invoice ${esc(active.invoiceNo)} · ${esc(active.customer)} · ${money(active.total)}. Items are fixed. Current stock and prices will be checked on payment.</p><button class="secondary" id="leave-invoice">Leave invoice payment</button>`:'<button class="secondary" id="save-invoice">Save unpaid invoice</button>';box.append(section);if(active){$('#cart-add').disabled=true;document.querySelectorAll('[data-remove]').forEach(b=>b.disabled=true);$('#leave-invoice').onclick=()=>{activeInvoice=null;cart=[];render();};}else $('#save-invoice').onclick=()=>openInvoiceForm();}
function showInvoice(id){$('#print-receipt').textContent='Print invoice';const i=state.invoices.find(i=>i.id===id);$('#receipt-content').innerHTML=`<strong>${esc(i.pharmacyName)}</strong><h2>Invoice</h2><p>${esc(i.invoiceNo)}<br>Issued ${esc(i.date)} · Due ${esc(i.due)}<br>Customer: ${esc(i.customer)}<br>Status: ${esc(i.status)}</p>`+table(['BRAND / GENERIC','BATCH','QUANTITY','UNIT PRICE','TOTAL'],i.lines.map(l=>`<tr><td>${esc(l.brand)}<small>${esc(l.generic)} ${esc(l.strength)}</small></td><td>${esc(l.batch)}</td><td>${packLineLabel(l)}</td><td>${money(l.sellPrice??l.unitPrice)} / ${esc(l.sellUnit||l.unit)}</td><td>${money(l.total)}</td></tr>`))+`<h3>Total: ${money(i.total)}</h3><p>${i.status==='Unpaid'?'Unpaid · not proof of payment. Stock is not reserved.':i.status==='Cancelled'?'Cancelled by '+esc(i.cancelledBy)+': '+esc(i.cancelReason):'Paid · see linked sales receipt.'}</p><small>No tax calculation or fiscal-invoice integration.</small>`;$('#receipt').showModal();}
$('#invoice-form').onsubmit=e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target)),at=new Date().toISOString();let next;if(invoiceAction)next=P.cancelInvoice(state,invoiceAction,d,at);else{next=structuredClone(state);next.invoices.push(P.createInvoice(state,cart,d,today(),uuid(),at));}persist(next,formRevision);$('#invoice-dialog').close();if(!invoiceAction)cart=[];go('invoices');toast(invoiceAction?'Invoice cancelled; history retained.':'Unpaid invoice saved. Stock unchanged.');}catch(e){$('#invoice-error').textContent=e.message;}};
$('#invoice-close').onclick=()=>$('#invoice-dialog').close();
function lossDetailTable(){return table(['DATE / STATUS','BRAND / GENERIC','BATCH / SUPPLIER','SHELF','QUANTITY LOST','LOSS AT COST','REASON / NOTE','RECORDED BY'],P.stockLossRows(state,today()).map(r=>{const b=state.batches.find(b=>b.id===r.batchId),m=state.medicines.find(m=>m.id===r.medicineId);return `<tr><td>${esc(r.date)}<small>${esc(r.status)}</small></td><td>${esc(m.brand)}<small>${esc(m.generic)} ${esc(m.strength)}</small></td><td>${esc(b.batch)}<small>${esc(b.supplier)}</small></td><td>${esc(m.shelf||'Unassigned')}</td><td>${r.qty} ${esc(m.unit)}</td><td>${money(r.value)}</td><td>${esc(r.reason)}<small>${esc(r.note)}</small></td><td>${esc(r.by)}</td></tr>`;}),'No stock losses recorded or expired stock on hand.');}
function renderLosses(){$('#content').innerHTML=lossPanel()+`<div class="section-body"><button id="loss-export" class="secondary">Export stock losses CSV</button><p>Each recorded write-off and expired batch still on hand is listed below. Temporary holds and supplier returns are excluded. Expiry rows show the labelled expiry month; their value is assessed today.</p></div>`+lossDetailTable();$('#loss-export').onclick=()=>csvFile('stock-losses-'+today()+'.csv',[['Date','Status','Brand','Generic','Batch','Quantity','Unit','Loss UGX','Reason','Note','Recorded by'],...P.stockLossRows(state,today()).map(r=>{const m=state.medicines.find(m=>m.id===r.medicineId),b=state.batches.find(b=>b.id===r.batchId);return [r.date,r.status,m.brand,m.generic,b.batch,r.qty,m.unit,r.value,r.reason,r.note,r.by];})]);}
function renderMovements(){const rows=P.stockMovements(state);$('#content').innerHTML=`<div class="section-body"><button id="movement-export" class="secondary">Export stock movements CSV</button><p>Grouped by receipt batch, starting with delivery and followed by sales and adjustments in recording order. Balance is physical stock for that receipt batch, including held stock. Temporary holds do not change quantity. Search by medicine, batch, supplier or receipt number.</p></div>`+table(['BRAND / GENERIC','BATCH','DATE / MOVEMENT','REFERENCE / RECORDED BY','UNITS IN / OUT','BATCH BALANCE','COST MOVEMENT'],rows.map(r=>{const b=state.batches.find(b=>b.id===r.batchId),m=state.medicines.find(m=>m.id===r.medicineId);return `<tr><td>${esc(m.brand)}<small>${esc(m.generic)} ${esc(m.strength)}</small></td><td>${esc(b.batch)}<small>${esc(b.supplier)}</small></td><td>${esc(r.date)}<small>${esc(r.type)}</small></td><td>${esc(r.reference)}<small>${esc(r.by)}</small></td><td>${r.delta>0?'+':''}${r.delta} ${esc(m.unit)}</td><td>${r.balance} ${esc(m.unit)}</td><td>${money(r.value)}</td></tr>`;}),'No stock movements yet.');$('#movement-export').onclick=()=>csvFile('stock-movements-'+today()+'.csv',[['Brand','Generic','Batch','Date','Movement','Reference','Recorded by','Quantity change','Unit','Batch balance','Cost movement UGX'],...rows.map(r=>{const b=state.batches.find(b=>b.id===r.batchId),m=state.medicines.find(m=>m.id===r.medicineId);return [m.brand,m.generic,b.batch,r.date,r.type,r.reference,r.by,r.delta,m.unit,r.balance,r.value];})]);}

let closingDay=today();
function renderClosing(){const r=P.dailySummary(state,closingDay),previous=state.closings.filter(c=>c.date===closingDay),last=previous.at(-1);$('#content').innerHTML=`<div class="section-body"><div class="compare-controls"><label>Business date<input id="closing-date" type="date" value="${esc(closingDay)}" max="${today()}"></label><button class="secondary" id="closing-export">Export day CSV</button></div><p>One cash drawer for this pharmacy. Cash sales below are net of change given. Mobile money and bank/card totals are recorded payments, not a bank-statement reconciliation. Unpaid invoices are excluded.</p><div class="stats">${[['Sales total',r.total],['Cash sales',r.totals.Cash],['Mobile money',r.totals['Mobile money']],['Bank / card',r.totals['Bank / card']]].map(([label,n])=>`<div class="stat"><label>${label}</label><strong>${money(n)}</strong></div>`).join('')}</div><p>${r.transactions} completed sale${r.transactions===1?'':'s'} · Additional cash in: ${money(r.cashIn)} · Cash out: ${money(r.cashOut)}</p>${last?`<p class="notice ${P.closingIsCurrent(state,last)?'':'error'}">Latest closing: revision ${last.revision}, by ${esc(last.recordedBy)}. ${P.closingIsCurrent(state,last)?'Includes all currently recorded sales and cash movements for this date.':'Sales or cash movements were added after this closing. Review and save a new revision.'}</p>`:''}<h3>Count the drawer</h3><form id="closing-form" class="fields">${field('Opening cash (UGX) *','opening','number',last?.opening??'','required min="0" max="1000000000000" step="0.01"')}${field('Cash counted (UGX) *','counted','number','','required min="0" max="1000000000000" step="0.01"')}${field('Counted by *','recordedBy','text','','required maxlength="100"')}${field('Difference / revision explanation','note','text','','maxlength="500"')}<p class="full" id="closing-calculation">Enter opening and counted cash to compare.</p><p class="full" id="closing-error" role="alert"></p><button type="submit">Save closing snapshot</button></form><p>Expected cash = opening cash + cash sales + additional cash in − cash out. Enter actual opening cash for this date; it is not carried forward automatically. A difference does not alter sales, profit or stock. Saved closings stay in history; corrections create a new revision. New sales remain possible after closing.</p><h3>Additional cash movements</h3><p>Record deposits into or withdrawals from this drawer, such as a bank deposit or petty cash withdrawal. Do not enter sales, change given, or opening cash again. These entries only reconcile cash; they do not record an expense or change medicine profit. Correct a mistaken entry with an opposite movement and reference it in the reason.</p><form id="cash-movement-form" class="fields"><label>Direction<select name="direction"><option value="in">Cash added</option><option value="out">Cash removed</option></select></label>${field('Amount (UGX) *','amount','number','','required min="0.01" max="1000000000000" step="0.01"')}${field('Reason / reference *','reason','text','','required maxlength="500"')}${field('Recorded by *','recordedBy','text','','required maxlength="100"')}<p class="full" id="cash-movement-error" role="alert"></p><button type="submit">Record cash movement</button></form></div>`+table(['DATE / TIME','DIRECTION','AMOUNT','REASON / REFERENCE','RECORDED BY'],state.cashMovements.filter(m=>m.date===closingDay).map(m=>`<tr><td>${esc(m.date)}<small>${esc(new Date(m.at).toLocaleString('en-GB',{timeZone:'Africa/Kampala'}))} EAT</small></td><td>${m.direction==='in'?'Cash added':'Cash removed'}</td><td>${money(m.amount)}</td><td class="wrap-cell">${esc(m.reason)}</td><td>${esc(m.recordedBy)}</td></tr>`),'No additional cash movements for this date.')+`<div class="section-body"><h3>Closing history for ${esc(closingDay)}</h3></div>`+table(['REVISION / RECORDED','COUNTED BY','EXPECTED / COUNTED','DIFFERENCE','EXPLANATION',''],[...previous].reverse().map(c=>`<tr><td>Revision ${c.revision}<small>${esc(new Date(c.at).toLocaleString('en-GB',{timeZone:'Africa/Kampala'}))} EAT</small></td><td>${esc(c.recordedBy)}</td><td>${money(c.expected)}<small>Counted ${money(c.counted)}</small></td><td>${money(c.variance)}<small>${c.variance<0?'Short':c.variance>0?'Over':'Balanced'}</small></td><td class="wrap-cell">${esc(c.note||'—')}</td><td><button class="link" data-closing-print="${esc(c.id)}">View / print</button></td></tr>`),'No closing saved for this date.');
$('#closing-date').onchange=e=>{if(!e.target.value||e.target.value>today()){toast('Choose today or an earlier date.');e.target.value=closingDay;return;}closingDay=e.target.value;render();};$('#closing-form').oninput=()=>{const d=Object.fromEntries(new FormData($('#closing-form')));if(d.opening===''||d.counted===''){$('#closing-calculation').textContent='Enter opening and counted cash to compare.';return;}const expected=P.cash(Number(d.opening)+r.totals.Cash+r.cashIn-r.cashOut),variance=P.cash(Number(d.counted)-expected);$('#closing-calculation').textContent=`Expected: ${money(expected)} · Counted: ${money(d.counted)} · ${variance<0?'Short':variance>0?'Over':'Balanced'}${variance!==0?': '+money(Math.abs(variance)):''}`;};$('#closing-form').onsubmit=e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));if(d.opening===''||d.counted==='')throw Error('Enter opening and counted cash.');const next=structuredClone(state),c=P.closingRecord(state,{...d,date:closingDay,opening:Number(d.opening),counted:Number(d.counted)},today(),uuid(),new Date().toISOString());next.closings.push(c);persist(next);render();toast('Closing snapshot saved.');}catch(err){$('#closing-error').textContent=err.message;}};$('#cash-movement-form').onsubmit=e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target)),next=structuredClone(state);next.cashMovements.push(P.cashMovement(state,{...d,date:closingDay,amount:Number(d.amount)},today(),uuid(),new Date().toISOString()));persist(next);render();toast('Cash movement recorded.');}catch(err){$('#cash-movement-error').textContent=err.message;}};document.querySelectorAll('[data-closing-print]').forEach(b=>b.onclick=()=>showClosing(b.dataset.closingPrint));$('#closing-export').onclick=()=>csvFile('daily-closing-'+closingDay+'.csv',[['Business date',closingDay],['Payment method','Sales UGX'],...Object.entries(r.totals),['Total sales',r.total],['Completed sales',r.transactions],[],['Cash movement','Amount UGX','Reason','Recorded by','Recorded at'],...state.cashMovements.filter(m=>m.date===closingDay).map(m=>[m.direction,m.amount,m.reason,m.recordedBy,m.at]),[],['Revision','Opening UGX','Cash sales UGX','Cash in UGX','Cash out UGX','Expected UGX','Counted UGX','Difference UGX','Counted by','Note','Recorded at'],...previous.map(c=>[c.revision,c.opening,c.summary.totals.Cash,c.summary.cashIn,c.summary.cashOut,c.expected,c.counted,c.variance,c.recordedBy,c.note,c.at])]);}
function showClosing(id){const c=state.closings.find(c=>c.id===id);$('#print-receipt').textContent='Print closing';$('#receipt-content').innerHTML=`<h2>Daily cash closing</h2><p>Business date: ${esc(c.date)} · Revision ${c.revision}<br>Counted by: ${esc(c.recordedBy)}<br>Recorded: ${esc(new Date(c.at).toLocaleString('en-GB',{timeZone:'Africa/Kampala'}))} EAT</p>`+table(['DESCRIPTION','UGX'],[['Opening cash',c.opening],['Cash sales (net of change)',c.summary.totals.Cash],['Additional cash in',c.summary.cashIn],['Cash out',c.summary.cashOut],['Expected cash',c.expected],['Counted cash',c.counted],['Difference (negative = short)',c.variance],['Mobile money sales',c.summary.totals['Mobile money']],['Bank / card sales',c.summary.totals['Bank / card']],['Total sales',c.summary.total]].map(([l,n])=>`<tr><td>${l}</td><td>${money(n)}</td></tr>`))+`<p>${c.summary.transactions} sales included.<br>Explanation: ${esc(c.note||'None')}<br>${P.closingIsCurrent(state,c)?'Matches current records for this date.':'Additional records exist. This is a historical snapshot.'}</p><small>Cash reconciliation only. This is not a sales receipt or a net-profit statement.</small>`;$('#receipt').showModal();}

let activeStocktake=null;
function countActorFields(){return field('Recorder name *','actorName','text','','required maxlength="100"')+`<label>Role *<select name="actorRole" required><option value="">Select role</option><option>Owner</option><option>Manager</option><option>Stock manager</option></select></label>`;}
function renderStocktake(){const sessions=state.stocktakes,selected=sessions.find(s=>s.id===activeStocktake),draft=sessions.find(s=>s.status==='Draft'),shelves=[...new Set(state.medicines.map(m=>m.shelf?.trim()||'Unassigned'))].sort();$('#content').innerHTML=`<div class="section-body"><p>Count each receipt batch using its configured units. Add whole cartons, loose blisters and individual units separately, without counting the same stock twice. Include quarantined and expired quantities; posting a count never releases a hold or expiry block. Written-off batches are excluded. Where the same batch has several receipts, allocate the physical quantity between those receipt rows once.</p>${draft?`<button id="resume-stocktake">Continue draft ${esc(draft.number)}</button>`:`<form id="start-stocktake" class="fields"><label>Count scope<select name="shelf"><option value="">All shelves</option>${shelves.map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('')}</select></label>${countActorFields()}<button type="submit">Start stocktake</button></form>`}<p id="stocktake-start-error" role="alert"></p><p class="note">Account preview automatically supplies the recorder identity. Save draft counts before leaving the tab. Differences are posted only when every selected batch has a count and every difference has an explanation.</p></div><div id="stocktake-detail"></div><div class="section-body"><h3>Stocktake sessions</h3></div>`+table(['NUMBER / DATE','SCOPE','STATUS','STARTED BY','BATCHES',''],[...sessions].reverse().map(s=>`<tr><td>${esc(s.number)}<small>${esc(s.date)}</small></td><td>${esc(s.shelf||'All shelves')}</td><td>${esc(s.status)}</td><td>${esc(s.createdBy)}</td><td>${s.lines.length}</td><td><button class="link" data-stocktake="${esc(s.id)}">Open</button></td></tr>`),'No stocktakes yet.');if($('#resume-stocktake'))$('#resume-stocktake').onclick=()=>{activeStocktake=draft.id;render();};if($('#start-stocktake'))$('#start-stocktake').onsubmit=e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target)),next=structuredClone(state),s=P.startStocktake(state,{shelf:d.shelf,name:d.actorName,role:d.actorRole},today(),uuid(),new Date().toISOString());next.stocktakes.push(s);persist(next);activeStocktake=s.id;render();toast('Stocktake draft started. Stock unchanged.');}catch(e){$('#stocktake-start-error').textContent=e.message;}};document.querySelectorAll('[data-stocktake]').forEach(b=>b.onclick=()=>{activeStocktake=b.dataset.stocktake;render();});if(selected)renderStocktakeDetail(selected);}
function renderStocktakeDetail(s){const editable=s.status==='Draft',changed=editable&&P.stocktakeChanged(state,s);$('#stocktake-detail').innerHTML=`<div class="section-body"><h3>${esc(s.number)} · ${esc(s.status)}</h3><p>Scope: ${esc(s.shelf||'All shelves')} · Started by ${esc(s.createdBy)}</p>${changed?'<p class="notice error">Stock or shelf assignments changed since this draft started. Posting is blocked. Cancel this draft and start a fresh count.</p>':''}${s.status==='Posted'?`<p>Posted by ${esc(s.postedBy)} · ${esc(s.postedDate)}. Shortages appear in Stock loss; all differences appear in Stock adjustments and Stock movements.</p>`:''}${s.status==='Cancelled'?`<p>Cancelled by ${esc(s.cancelledBy)}: ${esc(s.cancelReason)}</p>`:''}<button class="secondary" id="stocktake-export">Export this count CSV</button></div><form id="stocktake-counts">`+table(['BRAND / GENERIC','BATCH / RECEIPT','SHELF / STATUS','SYSTEM UNITS','PHYSICAL COUNT','DIFFERENCE','EXPLANATION'],s.lines.map((l,n)=>{const b=state.batches.find(b=>b.id===l.batchId),m=state.medicines.find(m=>m.id===b.medicineId);return `<tr><td>${esc(m.brand)}<small>${esc(m.generic)} ${esc(m.strength)} · ${esc(m.unit)}</small></td><td>${esc(b.batch)}<small>${esc(b.supplier)} · ${esc(b.invoice)}</small></td><td>${esc(m.shelf||'Unassigned')}<small>${P.expired(b,today())?'Expired':b.status==='quarantined'?'Quarantined':b.status==='writtenoff'?'Written off':'Available'}</small></td><td>${l.expected}</td><td>${editable?countPackFields(m,b,l,n):l.count??'Not counted'}</td><td data-count-diff="${n}">${l.count===null?'—':l.count-l.expected}</td><td>${editable?`<input name="reason-${n}" aria-label="Reason for ${esc(m.brand)} ${esc(b.batch)} ${esc(b.invoice)}" maxlength="400" value="${esc(l.reason)}">`:esc(l.reason||'—')}</td></tr>`;}))+`<div class="section-body">${editable?`<div class="fields">${countActorFields()}${field('Cancellation reason (only when cancelling)','cancelReason','text','','maxlength="400"')}</div><p id="stocktake-unsaved">Counts shown are the last saved draft.</p><p id="stocktake-review"></p><p id="stocktake-error" role="alert"></p><div class="row-actions"><button type="submit" name="operation" value="save">Save draft counts</button><button type="submit" name="operation" value="post" ${changed?'disabled':''}>Post stocktake adjustments</button><button type="button" class="secondary" id="cancel-stocktake">Cancel draft</button></div>`:''}</div></form><div class="section-body"><h3>Count history</h3>${s.history.length?s.history.map(h=>`<details><summary>${esc(h.action)} · ${esc(h.name)} (${esc(h.role)}) · ${esc(new Date(h.at).toLocaleString('en-GB',{timeZone:'Africa/Kampala'}))} EAT</summary>${h.counts?table(['RECEIPT BATCH','SAVED COUNT','REASON'],h.counts.map(c=>{const b=state.batches.find(b=>b.id===c.batchId);return `<tr><td>${esc(b?.batch)} · ${esc(b?.invoice)}</td><td>${c.count===null?'Not counted':esc(c.count)}${c.countParts?'<small>'+esc(c.countParts.map(p=>(p.quantity??0)+' '+p.unit).join(' + '))+'</small>':''}</td><td>${esc(c.reason)}</td></tr>`;})):`<p>${esc(h.reason||h.action)}</p>`}</details>`).join(''):'<p>No counts saved yet.</p>'}</div>`;
$('#stocktake-export').onclick=()=>csvFile(s.number.replaceAll('/','-')+'.csv',[['Stocktake',s.number],['Status',s.status],['Scope',s.shelf||'All shelves'],['Started by',s.createdBy],['Posted by',s.postedBy||''],[],['Brand','Generic','Strength','Batch','Supplier','Supplier invoice','Stock unit','System units at start','Physical count','Difference','Reason','Count breakdown'],...s.lines.map(l=>{const b=state.batches.find(b=>b.id===l.batchId),m=state.medicines.find(m=>m.id===b.medicineId);return [m.brand,m.generic,m.strength,b.batch,b.supplier,b.invoice,m.unit,l.expected,l.count??'',l.count===null?'':l.count-l.expected,l.reason,(l.countParts||[]).map(p=>(p.quantity??0)+' '+p.unit).join(' + ')];})]);if(!editable)return;wireCountPacks(s);
const form=$('#stocktake-counts'),actor=()=>{const d=Object.fromEntries(new FormData(form));return {name:d.actorName,role:d.actorRole,reason:d.cancelReason};},counts=()=>{const d=Object.fromEntries(new FormData(form));return s.lines.map((l,n)=>({batchId:l.batchId,count:d['count-'+n]===''?null:Number(d['count-'+n]),reason:d['reason-'+n],countParts:JSON.parse(document.querySelector('[data-count-index="'+n+'"]').dataset.parts||'null')}));};form.oninput=()=>{$('#stocktake-unsaved').textContent='Unsaved entries. Save draft counts before leaving this tab.';let differences=0,value=0;counts().forEach((c,n)=>{const delta=c.count===null?null:c.count-s.lines[n].expected;document.querySelector('[data-count-diff="'+n+'"]').textContent=delta===null?'—':delta;if(delta){differences++;value+=delta*state.batches.find(b=>b.id===c.batchId).unitCost;}});$('#stocktake-review').textContent=differences+' batch differences · Net purchase-cost adjustment: '+money(value);};form.onsubmit=e=>{e.preventDefault();try{const at=new Date().toISOString(),a=actor();let next=P.updateStocktake(state,s.id,counts(),a,at);if(e.submitter?.value==='post'){next=P.postStocktake(next,s.id,a,today(),at);const changed=next.adjustments.length-state.adjustments.length;if(!confirm('Post '+changed+' batch adjustments from this stocktake? Posted counts remain in history and cannot be edited.'))return;}persist(next);render();toast(e.submitter?.value==='post'?'Stocktake posted. Stock updated.':'Draft counts saved. Stock unchanged.');}catch(e){$('#stocktake-error').textContent=e.message;}};$('#cancel-stocktake').onclick=()=>{try{const next=P.cancelStocktake(state,s.id,actor(),new Date().toISOString());persist(next);render();toast('Draft cancelled. Stock unchanged.');}catch(e){$('#stocktake-error').textContent=e.message;}};}

let patientOpen='',clinicalKind='',clinicalId='',clinicalRevision=0,rxDraft=[];
const cTime=at=>new Date(at).toLocaleString('en-GB',{timeZone:'Africa/Kampala'})+' EAT';
const clinicalWarning=()=>'<p class="notice">Use fictional patients while testing. Clinical records do not check doses or authorize dispensing.</p>';
const patientName=id=>{const p=state.patients.find(p=>p.id===id);return p?p.number+' · '+p.name:'Unknown patient';};
const cButton=(label,kind,id='',pid='')=>`<button type="button" class="secondary" data-clinical="${kind}" data-id="${esc(id)}" data-patient="${esc(pid)}">${label}</button>`;
const cText=(label,name,value='')=>`<label class="full">${label}<textarea name="${name}" maxlength="4000" rows="3">${esc(value)}</textarea></label>`;
const cSelect=(label,name,options,value='')=>`<label>${label}<select name="${name}">${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`;}).join('')}</select></label>`;
const cSearch=(label,name,options,value='')=>`<div class="full clinical-picker"><label>${label}<input type="search" aria-label="Search ${label}" placeholder="Type to filter the visible list" data-filter-select="${name}"><select name="${name}" aria-label="${label}" size="4" required>${options.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select></label></div>`;
function bindClinical(){document.querySelectorAll('[data-clinical]').forEach(b=>b.onclick=()=>openClinical(b.dataset.clinical,b.dataset.id,b.dataset.patient));document.querySelectorAll('[data-patient-record]').forEach(b=>b.onclick=()=>{patientOpen=b.dataset.patientRecord;go('patients');});document.querySelectorAll('[data-print-rx]').forEach(b=>b.onclick=()=>printRx(b.dataset.printRx));}
function renderPatients(){$('#content').innerHTML=`<div class="section-body">${clinicalWarning()}${cButton('Add patient','patient')}</div>`+table(['PATIENT ID / NAME','BIRTH DATE / SEX','CONTACT','ALLERGY STATUS',''],state.patients.map(p=>`<tr><td><strong>${esc(p.number)}</strong><small>${esc(p.name)}</small></td><td>${esc(p.dob||'Not recorded')}<small>${esc(p.sex)}</small></td><td>${esc(p.phone)}</td><td>${esc(p.allergyStatus)}</td><td><button class="link" data-patient-record="${esc(p.id)}">Open record</button></td></tr>`),'No patient records yet.');const p=state.patients.find(p=>p.id===patientOpen);if(p){const visits=state.consultations.filter(v=>v.patientId===p.id);$('#content').insertAdjacentHTML('beforeend',`<section class="section-body"><h2>${esc(p.number)} · ${esc(p.name)}</h2><div class="row-actions">${cButton('Correct details','patient',p.id)}${cButton('Add consultation','visit','',p.id)}${cButton('Book appointment','appointment','',p.id)}${cButton('New prescription','rx','',p.id)}</div><p class="notice">${esc(p.allergyStatus)}${p.allergies?': '+esc(p.allergies):''}</p>${[['Birth date',p.dob],['Sex',p.sex],['Phone',p.phone],['Address',p.address],['Emergency contact',p.emergency],['Medical history',p.history],['Current medicines (manually maintained)',p.currentMedicines]].map(([k,v])=>`<p class="clinical-text"><b>${k}:</b> ${esc(v||'Not recorded')}</p>`).join('')}<h3>Consultations and clinical information</h3>${visits.length?[...visits].reverse().map(v=>`<article class="clinical-entry"><h3>${esc(v.date)} · ${esc(v.clinician)}</h3>${[['Presenting complaint',v.complaint],['Assessment',v.assessment],['Plan / follow-up',v.plan],['Tests / results',v.tests],['Blood pressure (mmHg)',v.bp],['Temperature (°C)',v.temperature],['Weight (kg)',v.weight],['Pulse (/min)',v.pulse]].filter(x=>x[1]).map(([k,t])=>`<p class="clinical-text"><b>${k}:</b> ${esc(t)}</p>`).join('')}<p>Recorded by ${esc(v.created.name)} · ${esc(cTime(v.created.at))}</p>${v.addenda.map(h=>`<blockquote class="clinical-text">${esc(h.note)}<p>Amendment by ${esc(h.name)} · ${esc(cTime(h.at))}</p></blockquote>`).join('')}${cButton('Add amendment','addendum',v.id)}</article>`).join(''):'<p>No consultations recorded.</p>'}<h3>Appointments</h3>${appointmentTable(p.id)}<h3>Prescriptions</h3>${prescriptionTable(p.id)}<details><summary>Patient correction history (${p.edits.length})</summary>${p.edits.map(h=>`<article class="clinical-entry"><p>${esc(h.name)} · ${esc(cTime(h.at))} · ${esc(h.reason)}</p>${Object.keys(h.after).filter(k=>h.before[k]!==h.after[k]).map(k=>`<p class="clinical-text">${esc(k)}: ${esc(h.before[k]||'Blank')} → ${esc(h.after[k]||'Blank')}</p>`).join('')}</article>`).join('')}</details></section>`);}bindClinical();}
function appointmentTable(pid){return table(['DATE / TIME (EAT)','PATIENT','PROVIDER / REASON','STATUS',''],state.appointments.filter(a=>!pid||a.patientId===pid).slice().sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).map(a=>`<tr><td>${esc(a.date)} ${esc(a.time)}<small>${a.minutes} minutes</small></td><td>${esc(patientName(a.patientId))}</td><td>${esc(a.provider)}<small>${esc(a.reason)}</small></td><td>${esc(a.status)}<details><summary>History</summary><p>Booked by ${esc(a.created.name)} · ${esc(cTime(a.created.at))}</p>${a.changes.map(h=>`<p>${esc(h.to)} · ${esc(h.name)} · ${esc(cTime(h.at))} · ${esc(h.reason)}</p>`).join('')}</details></td><td>${a.status==='Scheduled'?cButton('Update status','appointmentStatus',a.id):''}</td></tr>`),'No appointments recorded.');}
function renderAppointments(){$('#content').innerHTML=`<div class="section-body">${clinicalWarning()}${cButton('Book appointment','appointment')}<p>Times use East Africa Time. Overlaps are checked for the same patient or exactly matching provider/service name. Reschedule by cancelling and booking again. No automatic reminders are sent.</p></div>`+appointmentTable();bindClinical();}
function prescriptionTable(pid){return table(['PRESCRIPTION / DATE','PATIENT','PRESCRIBER','MEDICINES','STATUS',''],[...state.prescriptions].reverse().filter(r=>!pid||r.patientId===pid).map(r=>`<tr><td>${esc(r.number)}<small>${esc(r.date)}</small></td><td>${esc(r.patientNumber)} · ${esc(r.patientName)}</td><td>${esc(r.prescriber)}</td><td class="wrap-cell"><details><summary>${r.lines.length} medicine line(s)</summary>${r.lines.map(l=>`<p>${esc(l.brand)} / ${esc(l.generic)} ${esc(l.strength)}<br>${l.quantity} ${esc(l.unit)} · ${esc(l.dose)} · ${esc(l.route)} · ${esc(l.frequency)} · ${esc(l.duration)}</p>`).join('')}</details></td><td>${esc(r.status)}</td><td><button class="secondary" data-print-rx="${esc(r.id)}">View / print</button>${r.status!=='Cancelled'?cButton('Review / cancel','rxStatus',r.id):''}</td></tr>`),'No prescriptions recorded.');}
function renderPrescriptions(){$('#content').innerHTML=`<div class="section-body">${clinicalWarning()}${cButton('New prescription','rx')}<p>Transcribe an existing clinician prescription. Draft → Recorded means the source was checked; it does not authorize dispensing, deduct stock or prove supply. Cancel mistakes and create a replacement record.</p></div>`+prescriptionTable();bindClinical();}
function openClinical(kind,id='',pid=''){clinicalKind=kind;clinicalId=id;clinicalRevision=state.revision;rxDraft=[];const old=state.patients.find(p=>p.id===id)||{},titles={patient:id?'Correct patient details':'Add patient',appointment:'Book appointment',appointmentStatus:'Update appointment',visit:'Record consultation',addendum:'Add clinical amendment',rx:'New prescription draft',rxStatus:'Review prescription'};$('#clinical-title').textContent=titles[kind];$('#clinical-error').textContent='';let html='';if(['appointment','visit','rx'].includes(kind))html=cSearch('Patients','patientId',state.patients.map(p=>[p.id,p.number+' · '+p.name+' · '+(p.dob||'DOB unknown')]),pid)+'<p id="clinical-allergies" class="notice full"></p>';
if(kind==='patient')html=field('Patient name *','name','text',old.name||'','required maxlength="100"')+field('Date of birth','dob','date',old.dob||'','max="'+today()+'"')+cSelect('Sex','sex',['Unknown','Female','Male','Other'],old.sex||'Unknown')+field('Phone','phone','text',old.phone||'','maxlength="100"')+field('Address','address','text',old.address||'','maxlength="400"')+field('Emergency contact','emergency','text',old.emergency||'','maxlength="400"')+cSelect('Allergy status','allergyStatus',['Not assessed','No known allergies','Allergies reported'],old.allergyStatus||'Not assessed')+cText('Allergy details / reactions','allergies',old.allergies)+cText('Medical history / conditions','history',old.history)+cText('Current medicines (manually maintained)','currentMedicines',old.currentMedicines)+(id?field('Correction reason *','reason','text','','required maxlength="500"'):'');
if(kind==='appointment')html+=field('Date *','date','date',today(),'required min="'+today()+'"')+field('Time (EAT) *','time','time','','required')+field('Duration (minutes) *','minutes','number',30,'required min="1" max="480" step="1"')+field('Provider / service *','provider','text','','required maxlength="100"')+field('Reason *','reason','text','','required maxlength="500"');
if(kind==='visit')html+=field('Consultation date *','date','date',today(),'required max="'+today()+'"')+field('Clinician *','clinician','text','','required maxlength="100"')+'<label>Linked appointment (optional)<select name="appointmentId"></select></label>'+cText('Presenting complaint *','complaint')+cText('Assessment / clinical findings','assessment')+cText('Plan / follow-up','plan')+cText('Tests / results / related notes','tests')+field('Blood pressure (mmHg)','bp')+field('Temperature (°C)','temperature')+field('Weight (kg)','weight')+field('Pulse (/min)','pulse');
if(kind==='addendum'){const v=state.consultations.find(v=>v.id===id);html=`<p class="full">${esc(patientName(v.patientId))} · Consultation ${esc(v.date)}. Original notes remain unchanged.</p>`+cText('Amendment / correction and reason *','note');}
if(kind==='appointmentStatus')html=cSelect('New status','status',['Completed','Missed','Cancelled'])+field('Reason *','reason','text','','required maxlength="500"');
if(kind==='rx'){html+=field('Prescription date *','date','date',today(),'required max="'+today()+'"')+field('Prescriber *','prescriber','text','','required maxlength="100"')+field('Source reference','reference','text','','maxlength="120"')+'<label>Linked consultation (optional)<select name="consultationId"></select></label>'+cSearch('Medicines','medicineId',state.medicines.map(m=>[m.id,m.brand+' / '+m.generic+' '+m.strength+' · '+m.form+' · '+m.unit]))+['dose','route','frequency','duration'].map(k=>field(k[0].toUpperCase()+k.slice(1)+' *',k,'text','','maxlength="200"')).join('')+field('Quantity in smallest units *','quantity','number','','min="1" step="1"')+field('Additional directions','instructions','text','','maxlength="1000"')+'<button type="button" id="rx-add">Add medicine line</button><div class="full" id="rx-lines"></div>'+cText('Prescription notes','notes');}
if(kind==='rxStatus'){const r=state.prescriptions.find(r=>r.id===id);html=`<div class="full"><p>${esc(r.number)} · ${esc(r.patientNumber)} · ${esc(r.patientName)}<br>Prescriber: ${esc(r.prescriber)} · Source: ${esc(r.reference||'Not recorded')}<br>Allergy snapshot: ${esc(r.allergyStatus)} · ${esc(r.allergies)}</p>${table(['MEDICINE','DIRECTIONS','QUANTITY'],r.lines.map(l=>`<tr><td>${esc(l.brand)}<small>${esc(l.generic)} ${esc(l.strength)}</small></td><td class="wrap-cell">${esc(l.dose)} · ${esc(l.route)} · ${esc(l.frequency)} · ${esc(l.duration)}<small>${esc(l.instructions)}</small></td><td>${l.quantity} ${esc(l.unit)}</td></tr>`))}</div>`+cSelect('New status','status',r.status==='Draft'?['Recorded','Cancelled']:['Cancelled'])+field('Review / cancellation reason *','reason','text','','required maxlength="500"')+'<label class="full"><span><input type="checkbox" name="reviewed"> I checked the source prescription, patient, allergies and every medicine direction. This is a transcription record.</span></label>';}
html+=field('Recorded by *','actor','text','','required maxlength="100"');$('#clinical-fields').innerHTML=html;const form=$('#clinical-form');form.querySelectorAll('[data-filter-select]').forEach(input=>{const sel=form.elements.namedItem(input.dataset.filterSelect),opts=Array.from(sel.options).map(o=>[o.value,o.textContent]);input.oninput=()=>{const prev=sel.value;sel.innerHTML=opts.filter(o=>P.norm(o[1]).includes(P.norm(input.value))).map(([v,t])=>`<option value="${esc(v)}" ${v===prev?'selected':''}>${esc(t)}</option>`).join('');sel.dispatchEvent(new Event('change'));};});const ps=form.elements.namedItem('patientId');if(ps){ps.onchange=()=>{const p=state.patients.find(p=>p.id===ps.value);$('#clinical-allergies').textContent=p?p.number+' · '+p.name+' · '+p.allergyStatus+(p.allergies?': '+p.allergies:''):'Choose a patient.';for(const [name,list] of [['appointmentId',state.appointments],['consultationId',state.consultations]]){const sel=form.elements.namedItem(name);if(sel)sel.innerHTML='<option value="">None</option>'+list.filter(x=>x.patientId===ps.value).map(x=>`<option value="${esc(x.id)}">${esc(x.date)} · ${esc(x.time||x.clinician||'')}</option>`).join('');}};ps.onchange();}if(kind==='rx'){$('#rx-add').onclick=()=>{try{const d=Object.fromEntries(new FormData(form)),m=state.medicines.find(m=>m.id===d.medicineId);if(!m||!['dose','route','frequency','duration'].every(k=>d[k].trim())||!Number.isSafeInteger(Number(d.quantity))||Number(d.quantity)<1)throw Error('Select a medicine, complete directions and enter a whole positive quantity.');rxDraft.push(Object.fromEntries(['medicineId','dose','route','frequency','duration','quantity','instructions'].map(k=>[k,d[k]])));for(const k of ['dose','route','frequency','duration','quantity','instructions'])form.elements.namedItem(k).value='';drawRxLines();$('#clinical-error').textContent='';}catch(e){$('#clinical-error').textContent=e.message;}};drawRxLines();}$('#clinical-dialog').showModal();}
function drawRxLines(){$('#rx-lines').innerHTML=table(['MEDICINE / BRAND','DIRECTIONS','QUANTITY',''],rxDraft.map((l,i)=>{const m=state.medicines.find(m=>m.id===l.medicineId);return `<tr><td>${esc(m.brand)}<small>${esc(m.generic)} ${esc(m.strength)}</small></td><td class="wrap-cell">${esc(l.dose)} · ${esc(l.route)} · ${esc(l.frequency)} · ${esc(l.duration)}<small>${esc(l.instructions)}</small></td><td>${l.quantity} ${esc(m.unit)}</td><td><button type="button" class="link" data-remove-rx="${i}">Remove</button></td></tr>`;}),'Add each medicine to the prescription before saving.');document.querySelectorAll('[data-remove-rx]').forEach(b=>b.onclick=()=>{rxDraft.splice(Number(b.dataset.removeRx),1);drawRxLines();});}
function printRx(id){$('#print-receipt').textContent='Print prescription';const r=state.prescriptions.find(r=>r.id===id);$('#receipt-content').innerHTML=`<div class="receipt-head"><h2>${esc(state.settings.pharmacyName||'Pharmacy workspace')}</h2><h3>Prescription record · ${esc(r.status)}</h3><p>${esc(r.number)} · ${esc(r.date)}</p></div><p>Patient: ${esc(r.patientNumber)} · ${esc(r.patientName)}<br>Prescriber: ${esc(r.prescriber)}<br>Source: ${esc(r.reference||'Not recorded')}<br>Allergies at creation: ${esc(r.allergyStatus)} · ${esc(r.allergies)}</p>`+table(['MEDICINE','DIRECTIONS','QUANTITY'],r.lines.map(l=>`<tr><td>${esc(l.brand)}<small>${esc(l.generic)} ${esc(l.strength)} · ${esc(l.form)}</small></td><td>${esc(l.dose)} · ${esc(l.route)} · ${esc(l.frequency)} · ${esc(l.duration)}<small>${esc(l.instructions)}</small></td><td>${l.quantity} ${esc(l.unit)}</td></tr>`))+`<p class="clinical-text">${esc(r.notes)}</p><p>Recorded by ${esc(r.created.name)} · ${esc(cTime(r.created.at))}</p>${r.changes.map(h=>`<p>${esc(h.to)} · ${esc(h.name)} · ${esc(cTime(h.at))} · ${esc(h.reason)}</p>`).join('')}<p>Offline test record. Not dispensing authorization or proof of supply. No automated dose, interaction or contraindication checks.</p>`;$('#receipt').showModal();}
document.body.insertAdjacentHTML('beforeend','<dialog id="clinical-dialog"><form id="clinical-form"><div class="modal-head"><h2 id="clinical-title"></h2><button type="button" class="close" id="clinical-close" aria-label="Close clinical form">×</button></div><div class="fields" id="clinical-fields"></div><p id="clinical-error" role="alert"></p><div class="modal-footer"><button type="submit">Save clinical record</button></div></form></dialog>');
$('#clinical-close').onclick=()=>$('#clinical-dialog').close();$('#clinical-form').onsubmit=e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));d.reviewed=d.reviewed==='on';d.lines=rxDraft;if(clinicalKind==='rx'&&['dose','route','frequency','duration','quantity','instructions'].some(k=>d[k]?.trim()))throw Error('There is an unfinished medicine line. Add it to the prescription or clear those fields before saving.');const id=clinicalId||uuid(),next=P.clinicalChange(state,clinicalKind,d,today(),id,new Date().toISOString());persist(next,clinicalRevision);if(clinicalKind==='patient')patientOpen=id;else if(d.patientId)patientOpen=d.patientId;$('#clinical-dialog').close();go(clinicalKind.startsWith('rx')?'prescriptions':clinicalKind.startsWith('appointment')?'appointments':'patients');toast('Clinical record saved.');}catch(e){$('#clinical-error').textContent=e.message;}};

// Quick checkout opens the existing sale workspace without submitting or clearing it.
function openQuickCheckout(){
  if(document.querySelector('dialog[open]')||busy)return;
  if(tab!=='checkout')go('checkout');
  enhanceSelectors();
  const picker=$('#sale-medicine')?.previousElementSibling;
  const input=picker?.querySelector('input[role="combobox"]');
  if(input){input.focus();input.select();}
}
$('#quick-checkout').onclick=openQuickCheckout;
document.addEventListener('keydown',e=>{
  if(e.defaultPrevented||e.repeat||e.isComposing||e.keyCode===229||e.ctrlKey||e.metaKey||e.altKey||e.key?.toLowerCase()!=='n')return;
  const path=typeof e.composedPath==='function'?e.composedPath():[e.target];
  if(path.some(node=>node instanceof Element&&(node.matches('input,textarea,select,[role="textbox"],[role="searchbox"],[role="combobox"]')||node.isContentEditable)))return;
  if(document.querySelector('dialog[open]')||busy)return;
  e.preventDefault();
  openQuickCheckout();
});

const A=Access;
let accountSession=null,reportMonth=previousMonth(today()),accountSave=false;
function previousMonth(d){const date=new Date(d.slice(0,7)+'-01T12:00:00Z');date.setUTCMonth(date.getUTCMonth()-1);return date.toISOString().slice(0,7);}
function activeAccount(){return A.account(state,accountSession);}
function allowed(permission){return !state.access||A.can(state,accountSession,permission);}
const oldPersist=persist;
persist=function(next,expected=state.revision){if(state.access&&!accountSave)next=A.authorizeCommit(state,next,accountSession,new Date().toISOString(),uuid());oldPersist(next,expected);};
function persistAccounts(next,expected=state.revision){A.validateState(next);accountSave=true;try{persist(next,expected);}finally{accountSave=false;}}
const originalGo=go,originalRender=render;
go=function(next){if(state.access&&next!=='accounts'&&(!activeAccount()||!allowed(A.tabs[next])))next='accounts';return originalGo(next);};
render=function(){if(state.access&&tab!=='accounts'&&(!activeAccount()||!allowed(A.tabs[tab]))){go('accounts');return;}originalRender();applyAccessUI();};
function applyAccessUI(){const u=activeAccount();const identityLabel=state.access?(u?u.name+' · '+u.role:'Choose approved account'):'Account setup';if($('#account-indicator').textContent!==identityLabel)$('#account-indicator').textContent=identityLabel;document.querySelectorAll('[data-tab]').forEach(b=>{b.hidden=!!state.access&&b.dataset.tab!=='accounts'&&(!u||!allowed(A.tabs[b.dataset.tab]));});$('#quick-checkout').hidden=!!state.access&&!allowed('sell');
if(!state.access)return;
const controls=[['#add','catalogue.write'],['#receive,[data-receive]','receive'],['[data-edit-kind]:not([data-edit-kind="medicine"])','edit'],['[data-edit-kind="medicine"]',allowed('medicine.edit')?'medicine.edit':'edit'],['#alert-orders','procurement'],['#alert-adjust','adjust'],['[data-cancel-invoice]','invoice.cancel'],['#download-backup,#restore-backup','backup']];for(const [sel,right] of controls)document.querySelectorAll(sel).forEach(el=>el.hidden=!allowed(right));
const identityNames='input[name="recordedBy"],input[name="editorName"],input[name="actorName"],input[name="actor"],#adjust-by,#invoice-form input[name="name"]';
for(const el of document.querySelectorAll(identityNames)){if(u){el.value=u.name;el.readOnly=true;el.required=false;el.closest('label')?.setAttribute('hidden','');}}
for(const el of document.querySelectorAll('select[name="editorRole"],select[name="actorRole"]'))if(u){if(![...el.options].some(o=>o.value===u.role))el.add(new Option(u.role,u.role));el.value=u.role;el.required=false;el.closest('label')?.setAttribute('hidden','');}
for(const f of document.querySelectorAll('dialog form,#pharmacy-settings,#start-stocktake,#stocktake-counts,#closing-form,#cash-movement-form')){if(!u)continue;let note=f.querySelector('.account-stamp');if(!note){note=document.createElement('p');note.className='account-stamp notice';f.prepend(note);}const label='Recorded as '+u.name+' · '+u.designation+' · '+u.role+' · '+u.username;if(note.textContent!==label)note.textContent=label;}
}
// Populate identity before existing action handlers read FormData. No names are typed by staff.
document.addEventListener('submit',applyAccessUI,true);document.addEventListener('click',e=>{if(e.target.closest('button'))applyAccessUI();},true);
new MutationObserver(applyAccessUI).observe(document.body,{childList:true,subtree:true});
function approvalExample(){const pharmacyId='pharmacy-'+uuid(),pharmacyName=state.settings.pharmacyName||'Example Pharmacy';return {pharmacyId,pharmacyName,accounts:A.roles.map((role,i)=>({id:'approved-'+uuid(),pharmacyId,username:['admin','manager','pharmacist','cashier','stock.clerk','viewer','stock.manager'][i],name:'Example '+role,email:['admin','manager','pharmacist','cashier','stock','viewer','stock.manager'][i]+'@example.invalid',role,designation:role,status:'Active'}))};}
function loadApproval(config){const next=A.setup(state,config);persistAccounts(next);accountSession=null;go('accounts');toast('Approved-account preview loaded. Choose an account to test.');}
function renderAccounts(){const u=activeAccount(),c=state.access;$('#content').innerHTML=`<div class="section-body"><p class="notice">Development access: before enabling account preview, all workflows are available. In account preview, use Admin for testing to get all pharmacy permissions. This testing shortcut is for the offline build only. Account selection tests the permissions and recorded identity; it is not password authentication. No emails are sent. Online access must be enforced by the server for every pharmacy record.</p>${!c?`<h2>Provisioned accounts only</h2><p>Your team registers each pharmacy and approves its accounts. There is no public sign-up or staff account-creation form. Import the approved roster supplied by your team, or try the example roles.</p><div class="row-actions"><button id="try-access">Try example approved accounts</button><button class="secondary" id="approval-template">Download approval template</button><button class="secondary" id="import-approval">Import approved-account file</button></div><p>Enabling this preview attaches the current workspace records to one pharmacy. Make a backup first. The template is prepared outside the pharmacy app by your team; production approvals will come from the server.</p>`:`<h2>${esc(state.settings.pharmacyName)}</h2><p>Pharmacy reference: ${esc(c.pharmacyId)}</p><form id="select-account" class="fields"><label>Approved account for offline testing<select name="accountId"><option value="">Select account</option>${c.accounts.filter(a=>a.status==='Active').map(a=>`<option value="${esc(a.id)}" ${a.id===accountSession?'selected':''}>${esc(a.username)} · ${esc(a.name)} · ${esc(a.role)}</option>`).join('')}</select></label><div><button type="submit">Use selected account</button> <button type="button" id="test-admin">Use Admin for testing</button> <button type="button" class="secondary" id="end-session">End preview session</button></div></form>${u?`<p class="notice">Current identity: ${esc(u.name)} · ${esc(u.designation)} · ${esc(u.role)}. Critical action records use this identity automatically.</p>`:''}`}
<details><summary>Online login layout and account rules</summary><div class="fields"><label>Pharmacy name<input value="${esc(state.settings.pharmacyName)}" disabled></label><label>Username<input placeholder="Approved username" disabled></label><label>Password<input type="password" placeholder="Enabled when online" disabled autocomplete="off"></label><button disabled>Log in</button></div><p>The online login will resolve the pharmacy name to its fixed pharmacy ID, authenticate the username and password, then verify that the account belongs to that pharmacy. Names are labels; changing a pharmacy name must never move its data. Passwords are not collected or stored in this offline file.</p><p>Only your platform team can approve accounts or appoint Admins and Managers. Pharmacy Admins have all Manager rights. Admins and Managers can change designations, staff roles or suspend existing staff accounts in their own pharmacy. They cannot promote staff to Admin or Manager or alter their own rights. Job titles do not grant permissions by themselves.</p></details>
<details><summary>Online activation requirements</summary><p>Provisioning belongs to your platform team in a separate administration service. Disable public sign-up in both the website and authentication service. Approve each pharmacy, reserve its unique login name and create its approved accounts with a secure activation link. Passwords must never be placed in the roster or emailed as plain text.</p><p>Login order: pharmacy name, username, password. The server resolves the approved pharmacy name to a fixed pharmacy ID and checks current membership, account status and permissions on every request. All operational tables, files, reports and background jobs must carry that pharmacy ID, with database row-level policies and matching foreign keys to reject cross-pharmacy links. A client-selected pharmacy name is never sufficient authorization.</p><p>Record operator ID, name, designation, access role, server time, reason and before/after values in server-controlled audit history. Ignore operator identities submitted by the browser. Recheck current roles on each write so suspension or role changes take effect immediately. Management appointments can only be changed through the platform service; protect the last active Admin.</p><p>Commit access changes, audit entries and notification jobs in one server transaction. Send notices to the affected account and active pharmacy leadership. A scheduled server job runs on the 1st at 08:00 EAT for the previous month, with a unique pharmacy/month/recipient key, retries, delivery status and failure alerts. Recheck recipient membership before delivery and exclude clinical information. Password reset, rate limiting, encrypted transport, backups and secure session handling are required before real staff or patient use.</p><p>The offline preview does not provide these server controls. Its account selection, local audits and prepared emails demonstrate the workflows only.</p></details><details><summary>Role permissions</summary>${table(['ROLE','PERMISSIONS'],A.roles.map(r=>`<tr><td>${esc(r)}</td><td class="wrap-cell">${esc({Admin:'All pharmacy rights, including Manager rights and full backup/restore.',Manager:'Staff-role management, catalogue corrections, purchasing, stock receiving, holds, adjustments, sales, clinical records, finance, monthly reports and settings.',Pharmacist:'View stock, correct medicine details and packaging, checkout, invoices, sales and clinical records.',Cashier:'View stock, checkout, invoices and sales. No stock corrections or clinical records.','Stock clerk':'View stock, add catalogue products, receive stock and prepare procurement records. Medicine and packaging corrections with a reason. No posted-stock correction or staff rights.',Viewer:'View catalogue, batches, shelves, alerts and stock movements.','Stock manager':'Medicine and packaging corrections, purchasing, receiving, stocktakes, stock adjustments and reports. No staff administration or clinical access.'}[r])}</td></tr>`))}</details></div>`;
if(!c){$('#try-access').onclick=()=>{if(confirm('Enable the offline permissions preview for this workspace using example approved accounts? Export a backup first if needed.'))try{loadApproval(approvalExample());}catch(e){toast(e.message);}};$('#approval-template').onclick=()=>download('approved-pharmacy-template.json',JSON.stringify(approvalExample(),null,2),'application/json');$('#import-approval').onclick=()=>$('#approval-file').click();return;}
$('#test-admin').onclick=()=>{const admin=c.accounts.find(a=>a.role==='Admin'&&a.status==='Active');if(!admin){toast('No active Admin account is available.');return;}$('#select-account [name="accountId"]').value=admin.id;$('#select-account').requestSubmit();};$('#select-account').onsubmit=e=>{e.preventDefault();const id=new FormData(e.target).get('accountId');if(!A.account(state,id)){toast('Choose an active approved account.');return;}if(cart.length&&!confirm('Switching accounts clears the unsaved checkout basket. Continue?'))return;document.querySelectorAll('dialog[open]').forEach(d=>d.close());cart=[];activeInvoice=null;saleToken=uuid();accountSession=id;go('accounts');};$('#end-session').onclick=()=>{if(cart.length&&!confirm('End the preview session and discard its unsaved basket?'))return;accountSession=null;cart=[];activeInvoice=null;go('accounts');};
if(!u)return;
if(allowed('accounts')){$('#content').insertAdjacentHTML('beforeend',`<div class="section-body"><h2>Approved accounts</h2><p>Only existing approved staff accounts can be changed here. Management appointments remain with your platform team.</p></div>`+table(['USERNAME / NAME','DESIGNATION','ROLE / STATUS','EMAIL',''],c.accounts.map(a=>`<tr><td>${esc(a.username)}<small>${esc(a.name)}</small></td><td>${esc(a.designation)}</td><td>${esc(a.role)}<small>${esc(a.status)}</small></td><td>${esc(a.email)}</td><td>${!A.privileged(a.role)&&a.id!==u.id?`<button class="secondary" data-account-edit="${esc(a.id)}">Change access</button>`:'Platform-managed'}</td></tr>`)));document.querySelectorAll('[data-account-edit]').forEach(b=>b.onclick=()=>editAccess(b.dataset.accountEdit));}
if(allowed('reports'))renderAccountReports();
}
function editAccess(id){const a=state.access.accounts.find(a=>a.id===id),rev=state.revision;$('#access-title').textContent='Change access · '+a.username;$('#access-fields').innerHTML=field('Designation *','designation','text',a.designation,'required maxlength="100"')+cSelect('Staff permission role','role',A.staffRoles,a.role)+cSelect('Account status','status',['Active','Suspended'],a.status)+field('Reason for change *','reason','text','','required maxlength="500"')+`<p class="full">The affected account and active pharmacy Admins/Managers will receive a notice online. This preview prepares the email for review.</p>`;$('#access-error').textContent='';$('#access-form').onsubmit=e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target)),n=A.changeAccount(state,accountSession,id,d,d.reason,new Date().toISOString(),uuid());persistAccounts(n,rev);$('#access-dialog').close();render();toast('Account changed; email preview prepared.');}catch(e){$('#access-error').textContent=e.message;}};$('#access-dialog').showModal();}
function renderAccountReports(){const c=state.access,r=A.report(state,reportMonth);$('#content').insertAdjacentHTML('beforeend',`<section class="section-body"><h2>Monthly manager reports</h2><p>Planned online schedule: the 1st of each month at 08:00 EAT, covering the previous calendar month. Recipients are all active pharmacy Managers and Admins. The online scheduler and email provider are not connected yet.</p><label>Report month<input id="account-report-month" type="month" value="${esc(reportMonth)}" max="${previousMonth(today())}"></label><div class="stats">${[['Completed sales',r.transactions],['Sales income',money(r.revenue)],['Gross profit on sales',money(r.grossProfit)],['Stock received at cost',money(r.receivedCost)]].map(([k,v])=>`<div class="stat"><label>${k}</label><strong>${v}</strong></div>`).join('')}</div><div class="row-actions"><button id="prepare-monthly">Prepare monthly email previews</button><button id="report-download" class="secondary">Download report text</button></div><details><summary>Read monthly report</summary><pre class="account-report">${esc(A.reportText(state,r))}</pre></details><h2>Email previews</h2><p>Prepared locally. No delivery has taken place.</p>${table(['TYPE / DATE','RECIPIENTS','SUBJECT / STATUS',''],[...c.emails].reverse().map(e=>`<tr><td>${esc(e.kind)}<small>${esc(cTime(e.at))}</small></td><td class="wrap-cell">${e.recipients.map(esc).join('<br>')}</td><td>${esc(e.subject)}<small>${esc(e.status)}</small></td><td><details><summary>Read email</summary><pre class="account-report">${esc(e.body)}</pre></details></td></tr>`),'No email previews yet.')}<h2>Account and action history</h2>${table(['WHEN','ACCOUNT / ROLE','ACTION / RECORD','CHANGES / REASON'],[...c.audit].reverse().map(a=>`<tr><td>${esc(cTime(a.at))}</td><td>${esc(a.actor.name)}<small>${esc(a.actor.username)} · ${esc(a.actor.role)} · ${esc(a.actor.designation)}</small></td><td>${esc(a.action)}<small>${esc(a.collection)} · ${esc(a.recordId)}</small></td><td class="wrap-cell">${esc(a.fields.join(', '))}<small>${esc(a.reason)}</small>${a.before?`<small>${esc(JSON.stringify(a.before))} → ${esc(JSON.stringify(a.after))}</small>`:''}</td></tr>`),'No account-attributed changes yet.')}</section>`);$('#account-report-month').onchange=e=>{if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(e.target.value)||e.target.value>=today().slice(0,7)){toast('Choose a completed month.');return;}reportMonth=e.target.value;render();};$('#report-download').onclick=()=>download('monthly-pharmacy-'+reportMonth+'.txt',A.reportText(state,A.report(state,reportMonth)),'text/plain');$('#prepare-monthly').onclick=()=>{try{const next=A.queueMonthly(state,accountSession,reportMonth,today(),new Date().toISOString(),uuid());if(next.access.emails.length===state.access.emails.length){toast('Previews already exist for this month and its recipients.');return;}persistAccounts(next);render();toast('Monthly email previews prepared. Nothing sent.');}catch(e){toast(e.message);}};}
const originalBackup=backup;backup=function(){if(state.access&&!allowed('backup')){toast('Full backup is restricted to the pharmacy Admin.');return;}originalBackup();};
const originalRestore=$('#restore-file').onchange;
$('#restore-file').onchange=async e=>{if(!state.access){await originalRestore(e);if(state.access){accountSession=null;go('accounts');}return;}const f=e.target.files[0],rev=state.revision;if(!f)return;try{A.requireRight(state,accountSession,'backup');if(f.size>20*1024*1024)throw Error('Choose a backup smaller than 20 MB.');const next=P.validateBackup(JSON.parse(await f.text()));if(next.access?.pharmacyId!==state.access.pharmacyId)throw Error('This backup is not bound to the current pharmacy.');if(!confirm('Replace this pharmacy’s operational records from backup? Current approved accounts and account audit history will be retained.'))return;next.access=structuredClone(state.access);next.settings.pharmacyId=state.access.pharmacyId;next.access.pharmacyName=next.settings.pharmacyName;next.access.audit.push({id:uuid(),pharmacyId:state.access.pharmacyId,actor:A.actor(state,accountSession),at:new Date().toISOString(),collection:'backup',recordId:state.access.pharmacyId,action:'Operational backup restored',fields:[],reason:'Admin restored a same-pharmacy backup; current access configuration retained.'});persistAccounts(next,rev);cart=[];activeInvoice=null;go('accounts');toast('Backup restored. Account permissions retained.');}catch(e){toast('Restore failed: '+e.message);}finally{e.target.value='';}};
// Separate offline preview session: never serialize the selected account into backups.
document.body.insertAdjacentHTML('beforeend','<input type="file" id="approval-file" accept="application/json,.json" hidden><dialog id="access-dialog"><form id="access-form"><div class="modal-head"><h2 id="access-title"></h2><button type="button" class="close" id="access-close" aria-label="Close access form">×</button></div><div class="fields" id="access-fields"></div><p id="access-error" role="alert"></p><button type="submit">Save access change</button></form></dialog>');
$('#access-close').onclick=()=>$('#access-dialog').close();$('#approval-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>1024*1024)throw Error('Approval file is too large.');const config=JSON.parse(await f.text());A.validateConfig(config);if(confirm('Bind this workspace to '+config.pharmacyName+' with '+config.accounts.length+' approved accounts?'))loadApproval(config);}catch(e){toast(e.message);}finally{e.target.value='';}};
$('#account-indicator').onclick=()=>go('accounts');

window.addEventListener('storage',e=>{if(e.key===key){$('#notice').hidden=false;$('#notice').classList.add('error');$('#notice').textContent='Records changed in another tab. Reload before saving. Use one tab at a time.';}});if(state.access)go('accounts');else render();
